fn format_spreadsheet_chart_gauge_bands_for_moxel(
    node: &SpreadsheetChartXmlNode,
) -> Option<String> {
    if node.attributes.get("useTextStr").map(String::as_str) != Some("false")
        || node.attributes.get("useTooltipStr").map(String::as_str) != Some("false")
    {
        return None;
    }
    let items = spreadsheet_chart_children(node, "item");
    if items.len() > 1024 {
        return None;
    }
    let mut fields = vec!["1".to_string(), items.len().to_string()];
    for item in items {
        spreadsheet_chart_exact_child_names(
            item,
            &["begin", "end", "backColor", "text", "tooltip"],
        )?;
        let begin = spreadsheet_chart_number(item, "begin")?;
        let end = spreadsheet_chart_number(item, "end")?;
        fields.push(format!(
            "{{3,{begin},{end},{},{},{},\"\",0,\"\",0,{begin},{end}}}",
            spreadsheet_chart_color_for_moxel(spreadsheet_chart_text(item, "backColor")?)?,
            format_spreadsheet_chart_localized_for_moxel(spreadsheet_chart_child(item, "text")?)?,
            format_spreadsheet_chart_localized_for_moxel(spreadsheet_chart_child(
                item, "tooltip"
            )?)?
        ));
    }
    fields.extend(["0".to_string(), "0".to_string()]);
    Some(format!("{{{}}}", fields.join(",")))
}

fn format_spreadsheet_chart_axis_for_moxel(node: &SpreadsheetChartXmlNode) -> Option<String> {
    if node
        .children
        .iter()
        .any(|child| !matches!(child.name.as_str(), "minValue" | "maxValue"))
    {
        return None;
    }
    let min =
        spreadsheet_chart_optional_number(node, "minValue")?.unwrap_or_else(|| "0".to_string());
    let max =
        spreadsheet_chart_optional_number(node, "maxValue")?.unwrap_or_else(|| "0".to_string());
    Some(format!("{{0,0,{{0,1,{min},1,{max}}},0,0}}"))
}

fn format_spreadsheet_chart_rectangle_for_moxel(
    node: &SpreadsheetChartXmlNode,
) -> Option<Vec<String>> {
    spreadsheet_chart_exact_child_names(node, &["left", "right", "top", "bottom"])?;
    Some(vec![
        spreadsheet_chart_number(node, "left")?,
        spreadsheet_chart_number(node, "top")?,
        spreadsheet_chart_number(node, "right")?,
        spreadsheet_chart_number(node, "bottom")?,
    ])
}

fn format_spreadsheet_chart_cache_for_moxel(node: &SpreadsheetChartXmlNode) -> Option<String> {
    Some(
        format!(
            "{{{}, {},0,0,0,\"\",{{1,0}},{{1,0}},{{1,0}},0}}",
            spreadsheet_chart_color_for_moxel(spreadsheet_chart_text(node, "color")?)?,
            spreadsheet_chart_marker_code(spreadsheet_chart_text(node, "marker")?)?
        )
        .replace(", ", ","),
    )
}

fn spreadsheet_chart_scale_for_moxel(label_format: &str) -> String {
    format!(
        "{{2,0,0,2,{{1,0}},{{1,4,0.5,0.5,{{7,3,0,1,100}},{{3,4,{{0}}}},{{3,4,{{0}}}},1,{{3,0,{{0}},0,1,0,48312c09-257f-4b29-b280-284dd89efc1e}},{{3,4,{{0}}}},4,2,0}},2,0,0,{{3,4,{{0}}}},{{7,3,0,1,100}},{{3,4,{{0}}}},2,{label_format},0,{{3,4,{{0}}}},0,0,0,0,0,0}}"
    )
}

fn format_spreadsheet_chart_localized_for_moxel(node: &SpreadsheetChartXmlNode) -> Option<String> {
    if node.children.len() > 64 || node.children.iter().any(|child| child.name != "item") {
        return None;
    }
    let mut values = Vec::with_capacity(node.children.len());
    for item in &node.children {
        spreadsheet_chart_exact_child_names(item, &["lang", "content"])?;
        values.push(LocalizedString {
            lang: spreadsheet_chart_text(item, "lang")?.to_string(),
            content: spreadsheet_chart_text(item, "content")?.to_string(),
        });
    }
    Some(format_spreadsheet_number_format_for_moxel(&values))
}

fn spreadsheet_chart_line_for_moxel(node: &SpreadsheetChartXmlNode) -> Option<String> {
    let width = node.attributes.get("width")?.parse::<usize>().ok()?;
    if node.attributes.get("gap").map(String::as_str) != Some("false")
        || node.children.len() != 1
        || node.children.first()?.name != "style"
        || node.children.first()?.text.trim() != "Solid"
        || node
            .children
            .first()?
            .attributes
            .get("type")
            .is_none_or(|value| value.rsplit(':').next() != Some("ChartLineType"))
    {
        return None;
    }
    Some(format!(
        "{{4,0,{{0}},1,{width},0,e5cabe59-d992-4d31-8086-3116931aff81,0}}"
    ))
}

fn spreadsheet_chart_color_for_moxel(value: &str) -> Option<String> {
    match value {
        "auto" => Some("{3,4,{0}}".to_string()),
        "style:FormTextColor" => Some("{3,3,{-3}}".to_string()),
        "style:FormBackColor" => Some("{3,3,{-1}}".to_string()),
        "style:BorderColor" => {
            Some("{3,0,{0},0,0,0,48312c09-257f-4b29-b280-284dd89efc1e}".to_string())
        }
        _ => spreadsheet_direct_color_code(value).map(|color| format!("{{3,0,{{{color}}}}}")),
    }
}

fn spreadsheet_chart_marker_code(value: &str) -> Option<usize> {
    match value {
        "None" => Some(0),
        "Rect" => Some(1),
        "Circle" => Some(2),
        "Rhomb" => Some(3),
        _ => None,
    }
}

fn spreadsheet_chart_percent_fraction(value: &str) -> Option<String> {
    let value = spreadsheet_chart_normalize_number(value)?;
    let negative = value.starts_with('-');
    let unsigned = value.trim_start_matches('-');
    let (integer, fraction) = unsigned.split_once('.').unwrap_or((unsigned, ""));
    let digits = format!("{integer}{fraction}");
    let decimal_position = isize::try_from(integer.len()).ok()?.checked_sub(2)?;
    let mut result = if decimal_position <= 0 {
        format!(
            "0.{}{}",
            "0".repeat(usize::try_from(-decimal_position).ok()?),
            digits
        )
    } else {
        let split = usize::try_from(decimal_position).ok()?;
        format!("{}.{}", &digits[..split], &digits[split..])
    };
    while result.ends_with('0') {
        result.pop();
    }
    if result.ends_with('.') {
        result.pop();
    }
    if negative && result != "0" {
        result.insert(0, '-');
    }
    Some(result)
}

fn spreadsheet_chart_number(node: &SpreadsheetChartXmlNode, name: &str) -> Option<String> {
    spreadsheet_chart_text(node, name).and_then(spreadsheet_chart_normalize_number)
}

fn spreadsheet_chart_optional_number(
    node: &SpreadsheetChartXmlNode,
    name: &str,
) -> Option<Option<String>> {
    match spreadsheet_chart_children(node, name).as_slice() {
        [] => Some(None),
        [value] => Some(Some(spreadsheet_chart_node_number(value)?)),
        _ => None,
    }
}

fn spreadsheet_chart_node_number(node: &SpreadsheetChartXmlNode) -> Option<String> {
    spreadsheet_chart_normalize_number(node.text.trim())
}

fn spreadsheet_chart_normalize_number(value: &str) -> Option<String> {
    if value.is_empty()
        || !value.chars().enumerate().all(|(index, ch)| {
            ch.is_ascii_digit() || ch == '.' || (index == 0 && (ch == '-' || ch == '+'))
        })
        || value.chars().filter(|ch| *ch == '.').count() > 1
    {
        return None;
    }
    let value = value.strip_prefix('+').unwrap_or(value);
    let negative = value.starts_with('-');
    let unsigned = value.trim_start_matches('-');
    let (integer, fraction) = unsigned.split_once('.').unwrap_or((unsigned, ""));
    let integer = integer.trim_start_matches('0');
    let integer = if integer.is_empty() { "0" } else { integer };
    let fraction = fraction.trim_end_matches('0');
    let mut normalized = if fraction.is_empty() {
        integer.to_string()
    } else {
        format!("{integer}.{fraction}")
    };
    if negative && normalized != "0" {
        normalized.insert(0, '-');
    }
    Some(normalized)
}

fn spreadsheet_chart_bool_code(node: &SpreadsheetChartXmlNode, name: &str) -> Option<usize> {
    match spreadsheet_chart_text(node, name)? {
        "false" => Some(0),
        "true" => Some(1),
        _ => None,
    }
}

fn spreadsheet_chart_usize(node: &SpreadsheetChartXmlNode, name: &str) -> Option<usize> {
    spreadsheet_chart_text(node, name)?.parse::<usize>().ok()
}

fn spreadsheet_chart_text<'a>(node: &'a SpreadsheetChartXmlNode, name: &str) -> Option<&'a str> {
    let child = spreadsheet_chart_child(node, name)?;
    Some(child.text.as_str())
}

fn spreadsheet_chart_child<'a>(
    node: &'a SpreadsheetChartXmlNode,
    name: &str,
) -> Option<&'a SpreadsheetChartXmlNode> {
    let mut children = node.children.iter().filter(|child| child.name == name);
    let child = children.next()?;
    children.next().is_none().then_some(child)
}

fn spreadsheet_chart_children<'a>(
    node: &'a SpreadsheetChartXmlNode,
    name: &str,
) -> Vec<&'a SpreadsheetChartXmlNode> {
    node.children
        .iter()
        .filter(|child| child.name == name)
        .collect()
}

fn spreadsheet_chart_exact_child_names(
    node: &SpreadsheetChartXmlNode,
    expected: &[&str],
) -> Option<()> {
    (node.children.len() == expected.len()
        && node
            .children
            .iter()
            .zip(expected)
            .all(|(child, expected)| child.name == *expected))
    .then_some(())
}

fn format_spreadsheet_pictures_for_moxel(
    pictures: &[SpreadsheetDocumentXmlPicture],
    source: Option<&MetadataSourceContext>,
) -> Result<Vec<String>> {
    if pictures.is_empty() {
        return Ok(Vec::new());
    }
    let mut fields = Vec::with_capacity(pictures.len() + 1);
    fields.push(pictures.len().to_string());
    for picture in pictures {
        fields.push(format_spreadsheet_picture_for_moxel(picture, source)?);
    }
    Ok(fields)
}

fn format_spreadsheet_picture_for_moxel(
    picture: &SpreadsheetDocumentXmlPicture,
    source: Option<&MetadataSourceContext>,
) -> Result<String> {
    let Some(ref_name) = picture
        .ref_name
        .as_deref()
        .filter(|value| !value.is_empty())
    else {
        return Ok(format!("{{4,{}}}", picture.index));
    };
    if let Some(reference) = spreadsheet_standard_picture_ref(ref_name) {
        return Ok(format!("{{4,{},{{{reference}}}}}", picture.index));
    }
    let reference = if let Some(name) = ref_name.strip_prefix("v8ui:") {
        format!("CommonPicture.{name}")
    } else {
        ref_name.to_string()
    };
    let source = source.ok_or_else(|| {
        anyhow!("SpreadsheetDocument picture {ref_name} requires --source-root to resolve CommonPicture UUID")
    })?;
    let uuid = source.resolve_common_picture_uuid(&reference)?;
    Ok(format!("{{4,{},{{0,{uuid}}}}}", picture.index))
}

fn spreadsheet_standard_picture_ref(ref_name: &str) -> Option<String> {
    match ref_name {
        "v8ui:Print" | "StdPicture.Print" => Some("-13".to_string()),
        "v8ui:InputFieldCalculator" | "StdPicture.InputFieldCalculator" => Some("-6".to_string()),
        "v8ui:Information" | "StdPicture.Information" => {
            Some(format!("0,{STD_PICTURE_INFORMATION_UUID}"))
        }
        "v8ui:SaveFile" | "StdPicture.SaveFile" => Some(format!("0,{STD_PICTURE_SAVE_FILE_UUID}")),
        _ => None,
    }
}

fn format_spreadsheet_fonts_for_moxel(fonts: &[SpreadsheetDocumentXmlFont]) -> Vec<String> {
    fonts
        .iter()
        .filter_map(format_spreadsheet_font_for_moxel)
        .collect()
}

fn format_spreadsheet_font_for_moxel(font: &SpreadsheetDocumentXmlFont) -> Option<String> {
    match font.kind.as_str() {
        "Absolute" => {
            let face_name = font.face_name.as_deref().unwrap_or("Arial");
            let height = font.height.unwrap_or(8) * 10;
            let weight = spreadsheet_font_weight(font.bold);
            let scale = font.scale.unwrap_or(100);
            Some(format!(
                "{{7,0,575,{height},{},{},{},{weight},0,0,0,0,0,0,0,0,{},1,{scale}}}",
                bool_to_usize(font.italic),
                bool_to_usize(font.underline),
                bool_to_usize(font.strikeout),
                format_1c_string(face_name)
            ))
        }
        "StyleItem" => {
            let ref_code = spreadsheet_font_ref_code(font.ref_name.as_deref()?)?;
            let weight = spreadsheet_font_weight(font.bold);
            Some(format!(
                "{{7,2,60,{{{ref_code}}},{weight},{},{},{},1,100}}",
                bool_to_usize(font.italic),
                bool_to_usize(font.underline),
                bool_to_usize(font.strikeout)
            ))
        }
        _ => None,
    }
}

fn spreadsheet_font_weight(bold: bool) -> usize {
    if bold { 700 } else { 400 }
}

fn spreadsheet_font_ref_code(ref_name: &str) -> Option<i32> {
    match ref_name {
        "style:TextFont" => Some(-20),
        "style:NormalTextFont" => Some(-31),
        "style:LargeTextFont" => Some(-32),
        _ => None,
    }
}

pub fn pack_form_body_blob_from_module_text(
    base_blob: &[u8],
    module_text: &[u8],
) -> Result<PackedRawDeflatedBlob> {
    pack_form_body_blob_from_form_xml(base_blob, &[], Some(module_text))
}

pub fn pack_form_body_blob_from_form_xml(
    base_blob: &[u8],
    form_xml: &[u8],
    module_text: Option<&[u8]>,
) -> Result<PackedRawDeflatedBlob> {
    pack_form_body_blob_from_form_xml_with_source(base_blob, form_xml, module_text, None)
}

pub fn pack_form_body_blob_from_form_xml_with_source(
    base_blob: &[u8],
    form_xml: &[u8],
    module_text: Option<&[u8]>,
    source: Option<&MetadataSourceContext>,
) -> Result<PackedRawDeflatedBlob> {
    pack_form_body_blob_from_form_xml_with_source_and_assets(
        base_blob,
        form_xml,
        module_text,
        source,
        None,
    )
}

pub fn pack_form_body_blob_from_form_xml_with_source_and_assets(
    base_blob: &[u8],
    form_xml: &[u8],
    module_text: Option<&[u8]>,
    source: Option<&MetadataSourceContext>,
    form_item_assets_root: Option<&Path>,
) -> Result<PackedRawDeflatedBlob> {
    let inflated = inflate_raw(base_blob).context("failed to inflate base Form body blob")?;
    let mut plain =
        String::from_utf8(inflated).context("base Form body blob is not valid UTF-8")?;
    if !form_xml.is_empty() {
        let properties = parse_form_xml_body_properties(form_xml)?;
        let form_command_uuids = form_command_uuids_for_pack(&plain, &properties.commands)?;
        if properties.window_opening_mode.is_some()
            || properties.enter_key_behavior.is_some()
            || properties.save_window_settings.is_some()
            || !properties.title.is_empty()
            || properties.width.is_some()
            || properties.height.is_some()
            || properties.auto_title.is_some()
            || properties.auto_url.is_some()
            || properties.save_data_in_settings.is_some()
            || properties.auto_save_data_in_settings.is_some()
            || properties.group.is_some()
            || properties.scaling_mode.is_some()
            || properties.auto_time.is_some()
            || properties.use_posting_mode.is_some()
            || properties.repost_on_write.is_some()
            || properties.auto_fill_check.is_some()
            || !properties.command_set_excluded_commands.is_empty()
            || properties.use_for_folders_and_items.is_some()
            || properties.customizable.is_some()
            || properties.vertical_align.is_some()
            || properties.command_bar_location.is_some()
            || properties.vertical_scroll.is_some()
            || properties.horizontal_align.is_some()
            || properties.conversations_representation.is_some()
            || properties.show_title.is_some()
            || properties.show_close_button.is_some()
            || properties.report_result.is_some()
            || properties.details_data.is_some()
            || properties.report_form_type.is_some()
            || properties.auto_show_state.is_some()
            || properties.report_result_view_mode.is_some()
            || properties
                .view_mode_application_on_set_report_result
                .is_some()
            || properties.events_present
            || properties.auto_command_bar.is_some()
            || properties.child_items_present
            || !properties.child_items.is_empty()
        {
            let container = FormBodyContainer::parse(&plain)?;
            let mut layout = plain[container.layout_range.clone()].trim().to_string();
            patch_form_layout_properties(&mut layout, &properties)
                .context("failed to patch Form layout properties")?;
            if let Some(auto_command_bar) = &properties.auto_command_bar {
                let _ = patch_form_layout_auto_command_bar(
                    &mut layout,
                    auto_command_bar,
                    &properties.commands,
                    &form_command_uuids,
                    source,
                )
                .context("failed to patch Form layout AutoCommandBar")?;
            }
            patch_form_layout_events(&mut layout, &properties.events, properties.events_present)
                .context("failed to patch Form layout events")?;
            patch_form_layout_child_items(
                &mut layout,
                &properties.child_items,
                &properties.attributes,
                &properties.commands,
                &form_command_uuids,
                source,
                properties.child_items_present,
            )
            .context("failed to patch Form layout child items")?;
            plain.replace_range(container.layout_range, &layout);
        }
        if properties.commands_present {
            let container = FormBodyContainer::parse(&plain)?;
            if let Some(commands_range) = container.trailing_ranges.get(2).cloned() {
                let mut commands = plain[commands_range.clone()].trim().to_string();
                patch_form_body_commands(
                    &mut commands,
                    &properties.commands,
                    &form_command_uuids,
                    source,
                )
                .context("failed to patch Form body commands")?;
                plain.replace_range(commands_range, &commands);
            }
        }
        if properties.parameters_present {
            let container = FormBodyContainer::parse(&plain)?;
            if let Some(parameters_range) = container.trailing_ranges.get(1).cloned() {
                let mut parameters = plain[parameters_range.clone()].trim().to_string();
                patch_form_body_parameters(&mut parameters, &properties.parameters, source)
                    .context("failed to patch Form body parameters")?;
                plain.replace_range(parameters_range, &parameters);
            }
        }
        if properties.attributes_present {
            let container = FormBodyContainer::parse(&plain)?;
            if let Some(attributes_range) = container.trailing_ranges.first().cloned() {
                let mut attributes = plain[attributes_range.clone()].trim().to_string();
                patch_form_body_attributes(&mut attributes, &properties.attributes, source)
                    .context("failed to patch Form body attributes")?;
                patch_form_body_attributes_conditional_appearance(
                    &mut attributes,
                    properties.attributes_conditional_appearance.as_ref(),
                )
                .context("failed to patch Form body Attributes conditional appearance")?;
                plain.replace_range(attributes_range, &attributes);
            }
        }
        if properties.command_interface_present {
            let container = FormBodyContainer::parse(&plain)?;
            if let Some(command_interface_range) = container.trailing_ranges.get(3).cloned() {
                let mut command_interface =
                    plain[command_interface_range.clone()].trim().to_string();
                patch_form_command_interface(
                    &mut command_interface,
                    &properties.command_interface_items,
                    source,
                )
                .context("failed to patch Form command interface")?;
                plain.replace_range(command_interface_range, &command_interface);
            }
        }
    }
    if let Some(module_text) = module_text {
        let container = FormBodyContainer::parse(&plain)?;
        let module_text = std::str::from_utf8(module_text)
            .context("Form module text is not valid UTF-8")?
            .trim_start_matches('\u{feff}');
        plain.replace_range(container.module_range, &format_1c_string(module_text));
    }
    if let Some(form_item_assets_root) = form_item_assets_root {
        patch_form_item_picture_assets(&mut plain, form_item_assets_root)?;
    }
    let blob = deflate_raw(plain.as_bytes())?;
    let output_sha256 = hex_sha256(&blob);
    Ok(PackedRawDeflatedBlob {
        blob,
        plain_bytes: plain.len(),
        output_sha256,
    })
}


/// The settings composer a form with no composer settings carries.
///
/// The blob is not in the source at all: two spellings account for 11 842 of
/// the 12 507 ERP УХ bodies and nothing in the XML separates them, so the
/// writer picks the self-closed one -- what a newly created form carries --
/// and the round trip closes on the second export rather than on the original
/// database. See evidence/body-frame-20260921.md.
const NATIVE_EMPTY_SETTINGS: &str = "{#base64:}";


/// The `{22,…}` kind uuid a child of this tag is filed under.
fn native_child_kind_uuid(tag: &str) -> Option<&'static str> {
    use crate::compiler::bodies::form_native::child_kind_uuid;
    Some(match tag {
        "UsualGroup" | "Pages" | "Page" | "ButtonGroup" | "CommandBar" | "ContextMenu"
        | "Popup" | "ColumnGroup" => child_kind_uuid(22)?,
        "Button" => child_kind_uuid(31)?,
        "LabelDecoration" | "PictureDecoration" => child_kind_uuid(12)?,
        "Table" => child_kind_uuid(55)?,
        _ => child_kind_uuid(37)?,
    })
}

/// A tri-state the way every native record reads one.
const fn native_flag(value: Option<bool>) -> Option<bool> {
    value
}

/// What the native writer needs to place a `<DataPath>`: the form's own
/// attribute, column and item tables, and the configuration source tree a
/// dotted path walks into.
///
/// Built once per form; the configuration objects behind it are parsed once
/// per run, however many paths name them.
struct NativeDataPaths<'a> {
    form: DataPathForm,
    source: Option<&'a MetadataSourceContext>,
}

impl NativeDataPaths<'_> {
    /// Member 11 of the record, or `None` when the path names something the
    /// measured rule cannot place -- which refuses the form.
    fn resolve(&self, data_path: &str) -> Option<String> {
        crate::compiler::bodies::form_native::resolve_form_data_path(
            &self.form,
            self.source
                .map(|source| source as &dyn ConfigurationObjects),
            data_path,
        )
    }
}

/// The form's own half of the data-path tables, read off `Form.xml`.
fn native_data_path_form(properties: &FormXmlBodyProperties) -> DataPathForm {
    let mut form = DataPathForm::default();
    for attribute in &properties.attributes {
        let columns = attribute
            .columns
            .iter()
            .map(|column| {
                (
                    column.name.clone(),
                    DataPathColumn {
                        id: column.id.clone(),
                        types: column.spec.types.clone(),
                    },
                )
            })
            .collect::<BTreeMap<_, _>>();
        let mut additional_columns = BTreeMap::<String, BTreeMap<String, DataPathColumn>>::new();
        for block in &attribute.additional_columns {
            let table = additional_columns.entry(block.table.clone()).or_default();
            for column in &block.columns {
                // An additional column's own `<Type>` is not read, so a path
                // that walks *past* one into a typed context refuses instead
                // of guessing. A path that walks into another additional
                // column still places: those are found by the dotted prefix,
                // not by the type.
                table.insert(
                    column.name.clone(),
                    DataPathColumn {
                        id: column.id.clone(),
                        types: Vec::new(),
                    },
                );
            }
        }
        form.attributes.insert(
            attribute.name.clone(),
            DataPathAttribute {
                id: attribute.id.clone(),
                types: attribute.types.clone(),
                columns,
                additional_columns,
            },
        );
    }
    // `properties.child_items` is flat and carries every item, but in the
    // order each one *closed*; walking the tree from the roots is document
    // order, which is the order the first of two items of one name wins in.
    let roots = properties
        .child_items
        .iter()
        .filter(|item| item.depth == 0)
        .collect::<Vec<_>>();
    collect_native_data_path_items(roots.into_iter(), &mut form.items);
    if let Some(bar) = &properties.auto_command_bar {
        collect_native_data_path_items(bar.child_items.iter(), &mut form.items);
    }
    form
}

/// Every named item of the form, by name, with its id and its `<DataPath>`.
fn collect_native_data_path_items<'a>(
    items: impl Iterator<Item = &'a FormXmlChildItem>,
    out: &mut BTreeMap<String, DataPathItem>,
) {
    for item in items {
        out.entry(item.name.clone()).or_insert_with(|| DataPathItem {
            id: item.id.clone(),
            data_path: item.data_path.clone(),
        });
        collect_native_data_path_items(item.child_items.iter(), out);
    }
}

/// `<MobileDeviceCommandBarContent>` as the root trailer stores it.
///
/// An `<xr:Value>` names a form **item**, never a `<Command>`: in the ten
/// forms of the two corpora where the two share a name, all ten store the
/// item's id. The lookup therefore runs over the item tree -- which includes a
/// table's own `<AutoCommandBar>` and a field's `<ExtendedTooltip>` -- and a
/// name it does not answer refuses the form.
fn native_mobile_device_command_bar_content(
    properties: &FormXmlBodyProperties,
    items: &BTreeMap<String, DataPathItem>,
) -> Result<String> {
    let Some(content) = properties.mobile_device_command_bar_content.as_deref() else {
        return Ok("{50,0}".to_string());
    };
    if content.is_empty() {
        return Err(anyhow!(
            "an empty <MobileDeviceCommandBarContent> is not measured"
        ));
    }
    let mut tooltips = BTreeMap::new();
    for item in &properties.child_items {
        if let Some(tooltip) = &item.extended_tooltip {
            tooltips
                .entry(tooltip.name.clone())
                .or_insert_with(|| tooltip.id.clone());
        }
    }
    let mut ids = Vec::with_capacity(content.len());
    for item in content {
        // All 214 items of both corpora spell the presentation empty and the
        // check state `0`, and the record holds exactly two members each, so
        // neither reaches it. A form that spells one otherwise is refused.
        if item
            .presentation
            .as_deref()
            .is_some_and(|value| !value.is_empty())
        {
            return Err(anyhow!(
                "<MobileDeviceCommandBarContent> names a presentation"
            ));
        }
        if item
            .check_state
            .as_deref()
            .is_some_and(|value| !matches!(value, "" | "0"))
        {
            return Err(anyhow!("<MobileDeviceCommandBarContent> names a check state"));
        }
        let Some(name) = item
            .value
            .as_deref()
            .map(str::trim)
            .filter(|value| !value.is_empty())
        else {
            ids.push("0".to_string());
            continue;
        };
        let found = items
            .get(name)
            .map(|item| item.id.clone())
            .or_else(|| tooltips.get(name).cloned());
        match found {
            Some(id) => ids.push(id),
            None => {
                return Err(anyhow!(
                    "<MobileDeviceCommandBarContent> names {name}, which is not a form item"
                ));
            }
        }
    }
    Ok(
        crate::compiler::bodies::form_native::format_mobile_device_command_bar_content(
            &ids.iter().map(String::as_str).collect::<Vec<_>>(),
        ),
    )
}

/// Member 9 of a form attribute's record: its `<Save>`.
///
/// Each `<Field>` is a data path rooted at the attribute's own name, and the
/// stored path is that path with its leading segment removed -- `{0}` for a
/// field that is the attribute's own name, `{1,{0,<uuid>}}` for one that
/// walks one step into the object the attribute is typed as.
///
/// Two things are refused rather than guessed:
///
/// * a `<Field>` that does not start with the attribute's name -- 19 entries
///   of ERP УХ and none of BSP, each storing a one-segment path whose id the
///   attribute's own type does not answer;
/// * a segment that is not `{0,<uuid>}`, which is the numeric sub-field code
///   of a builtin type such as `v8:StandardPeriod`. The code is an ordinal
///   inside that type's own field list rather than a name-to-number table --
///   `Variant` is `2` under one type and `0` under another -- so 88 ERP УХ
///   entries and 0 BSP entries stay outside this writer.
fn native_form_attribute_save(
    attribute: &FormXmlAttribute,
    data_paths: &NativeDataPaths<'_>,
) -> Result<String> {
    let Some(fields) = attribute.save.as_deref() else {
        return Ok("{0,0}".to_string());
    };
    if fields.is_empty() {
        return Err(anyhow!("an empty <Save> is not measured"));
    }
    let mut paths = Vec::with_capacity(fields.len());
    for field in fields {
        let field = field.trim();
        if field == attribute.name {
            paths.push("{0}".to_string());
            continue;
        }
        if !field.starts_with(&format!("{}.", attribute.name)) {
            return Err(anyhow!(
                "<Save> names {field}, which is not rooted at the attribute"
            ));
        }
        let resolved = data_paths
            .resolve(field)
            .ok_or_else(|| anyhow!("<Save> names {field}, which the writer cannot place"))?;
        // `{<count>,<segment>…}`, the attribute's own segment first.
        let ranges = scan_braced_fields(&resolved, 0)?;
        let Some(tail) = ranges.get(2..) else {
            return Err(anyhow!("<Save> names {field}, which resolved to no segment"));
        };
        let segments = tail
            .iter()
            .map(|range| resolved[range.clone()].trim().to_string())
            .collect::<Vec<_>>();
        if !segments.iter().all(|segment| {
            form_attribute_save_segment_uuid(segment).is_some()
        }) {
            return Err(anyhow!(
                "<Save> names {field}, whose sub-field code is not measured"
            ));
        }
        paths.push(format!("{{{},{}}}", segments.len(), segments.join(",")));
    }
    Ok(crate::compiler::bodies::form_native::format_form_attribute_save(&paths))
}

/// The uuid of a resolved `<Save>` segment, when it is the `{0,<uuid>}` the
/// measurement read -- the uuid of an attribute of the metadata object the
/// form attribute is typed as.
fn form_attribute_save_segment_uuid(segment: &str) -> Option<&str> {
    let rest = segment.strip_prefix("{0,")?.strip_suffix('}')?;
    (rest.len() == 36
        && rest
            .bytes()
            .all(|byte| byte.is_ascii_hexdigit() || byte == b'-'))
    .then_some(rest)
}

/// One child item, as the `(kind uuid, record)` pair its parent files it under.
///
/// Fail-closed: a tag the writers have not measured, or a property whose
/// spelling they cannot place, refuses the whole form.
#[allow(clippy::too_many_arguments)]
fn format_native_child_item(
    item: &FormXmlChildItem,
    data_paths: &NativeDataPaths<'_>,
    command_ids: &BTreeMap<String, String>,
    items: &BTreeMap<String, NativeItemTarget>,
    main_attribute_class: &str,
    source: Option<&MetadataSourceContext>,
) -> Result<(&'static str, String)> {
    use crate::compiler::bodies::form_native as native;

    let kind_uuid = native_child_kind_uuid(&item.tag)
        .ok_or_else(|| anyhow!("no kind uuid for <{}>", item.tag))?;
    let title = format_form_title_value(&item.title);
    let tooltip_title = format_form_title_value(&item.tooltip);
    let extended_tooltip = item.extended_tooltip.as_ref().map(|tooltip| {
        native::format_extended_tooltip(&tooltip.id, &tooltip.name)
    });

    // A <ContextMenu> is itself a child item; a field keeps it in a member of
    // its own rather than among its children.
    let (context_menu, children): (Option<&FormXmlChildItem>, Vec<&FormXmlChildItem>) = {
        let mut menu = None;
        let mut rest = Vec::new();
        for child in &item.child_items {
            if child.tag == "ContextMenu" && menu.is_none() {
                menu = Some(child);
            } else {
                rest.push(child);
            }
        }
        (menu, rest)
    };

    if let Some(kind) = native::native_group_kind(&item.tag) {
        let mut records = Vec::new();
        for child in item.child_items.iter() {
            records.push(format_native_child_item(
                child,
                data_paths,
                command_ids,
                items,
                main_attribute_class,
                source,
            )?);
        }
        let payload = native_container_payload(item, data_paths, source)?;
        let record = native::format_group_item(&native::NativeGroupItem {
            id: &item.id,
            kind,
            name: &item.name,
            title: &title,
            tooltip_title: &tooltip_title,
            enable_content_change: item.enable_content_change.unwrap_or(false),
            enabled: item.enabled.unwrap_or(true),
            read_only: item.read_only.unwrap_or(false),
            width: item.width.as_deref(),
            height: item.height.as_deref(),
            horizontal_stretch: native_flag(item.horizontal_stretch),
            vertical_stretch: native_flag(item.vertical_stretch),
            payload: &payload,
            children: &records
                .iter()
                .map(|(uuid, record)| (*uuid, record.clone()))
                .collect::<Vec<_>>(),
            visible: item.visible.unwrap_or(true),
            extended_tooltip: extended_tooltip.as_deref(),
            ..native::NativeGroupItem::default()
        })
        .ok_or_else(|| anyhow!("<{}> names something the writer cannot place", item.tag))?;
        return Ok((kind_uuid, record));
    }

    if item.tag == "Table" {
        let record = format_native_table(item, data_paths, command_ids, items, main_attribute_class, source)?;
        return Ok((kind_uuid, record));
    }

    if let Some(kind) = native::native_field_kind(&item.tag) {
        let payload = native_field_payload(item, source)?;
        let data_path = match item.data_path.as_deref() {
            Some(path) => data_paths
                .resolve(path)
                .ok_or_else(|| anyhow!("<{}> binds to {path}, which the writer cannot place", item.tag))?,
            None => "{0}".to_string(),
        };
        let menu = match context_menu {
            Some(menu) => native::format_field_context_menu(&menu.id, &menu.name),
            None => return Err(anyhow!("a field with no context menu is not measured")),
        };
        let tooltip = extended_tooltip
            .ok_or_else(|| anyhow!("a field with no extended tooltip is not measured"))?;
        let record = native::format_field_item(&native::NativeFieldItem {
            id: &item.id,
            kind,
            name: &item.name,
            title_location: item.title_location.map(native_title_location),
            title: &title,
            tooltip_title: &tooltip_title,
            data_path: &data_path,
            enabled: item.enabled.unwrap_or(true),
            read_only: item.read_only.unwrap_or(false),
            skip_on_input: native_flag(item.skip_on_input),
            default_item: item.default_item.unwrap_or(false),
            show_in_header: item.show_in_header.unwrap_or(true),
            show_in_footer: item.show_in_footer.unwrap_or(true),
            cell_hyperlink: item.cell_hyperlink.unwrap_or(false),
            tooltip_representation: item.tooltip_representation.map(native_tooltip_representation),
            group_horizontal_align: item.group_horizontal_align.map(native_group_horizontal_align),
            group_vertical_align: item.group_vertical_align.map(native_vertical_align_spelling),
            horizontal_align: item.horizontal_align.map(native_horizontal_align_spelling),
            vertical_align: item.vertical_align.map(native_vertical_align_spelling),
            fixing_in_table: item.fixing_in_table.map(native_fixing_in_table_spelling),
            edit_mode: item.edit_mode.map(|value| match value {
                FormXmlEditMode::Directly => "Directly",
                FormXmlEditMode::EnterOnInput => "EnterOnInput",
            }),
            auto_cell_height: item.auto_cell_height.unwrap_or(false),
            payload: &payload,
            context_menu: &menu,
            visible: item.visible.unwrap_or(true),
            extended_tooltip: &tooltip,
            ..native::NativeFieldItem::default()
        })
        .ok_or_else(|| anyhow!("<{}> names something the writer cannot place", item.tag))?;
        let _ = children;
        return Ok((kind_uuid, record));
    }

    if item.tag == "Button" {
        let tooltip = extended_tooltip
            .ok_or_else(|| anyhow!("a button with no extended tooltip is not measured"))?;
        let command = native_button_command(item, command_ids, items, main_attribute_class)?;
        let record = native::format_button_item(&native::NativeButtonItem {
            id: &item.id,
            name: &item.name,
            title: &title,
            enabled: item.enabled.unwrap_or(true),
            command: &command,
            representation: item.button_representation.map(native_button_representation),
            default_button: item.default_button.unwrap_or(false),
            default_item: item.default_item.unwrap_or(false),
            tooltip_representation: item.tooltip_representation.map(native_tooltip_representation),
            group_horizontal_align: item.group_horizontal_align.map(native_group_horizontal_align),
            group_vertical_align: item.group_vertical_align.map(native_vertical_align_spelling),
            location_in_command_bar: item.location_in_command_bar.map(|value| match value {
                FormXmlButtonLocationInCommandBar::InCommandBar => "InCommandBar",
                FormXmlButtonLocationInCommandBar::InAdditionalSubmenu => "InAdditionalSubmenu",
                FormXmlButtonLocationInCommandBar::InCommandBarAndInAdditionalSubmenu => {
                    "InCommandBarAndInAdditionalSubmenu"
                }
            }),
            width: item.width.as_deref(),
            height: item.height.as_deref(),
            visible: item.visible.unwrap_or(true),
            skip_on_input: native_flag(item.skip_on_input),
            extended_tooltip: &tooltip,
            auto_max_width: item.auto_max_width.unwrap_or(true),
            max_width: item.max_width.as_deref(),
            auto_max_height: item.auto_max_height.unwrap_or(true),
            max_height: item.max_height.as_deref(),
            horizontal_stretch: item.horizontal_stretch.unwrap_or(false),
            vertical_stretch: item.vertical_stretch.unwrap_or(false),
            ..native::NativeButtonItem::default()
        })
        .ok_or_else(|| anyhow!("<Button> names something the writer cannot place"))?;
        return Ok((kind_uuid, record));
    }

    if matches!(item.tag.as_str(), "LabelDecoration" | "PictureDecoration") {
        let menu = match context_menu {
            Some(menu) => native::format_field_context_menu(&menu.id, &menu.name),
            None => return Err(anyhow!("a decoration with no context menu is not measured")),
        };
        let tooltip = extended_tooltip
            .ok_or_else(|| anyhow!("a decoration with no extended tooltip is not measured"))?;
        let text_color = native_scalar_color(item, "TextColor", source)?;
        // Member 14 is `<TextColor>` and member 15 is `<Font>`; the payload at
        // member 18 carries neither. Both were measured on the two corpora --
        // `<TextColor>` maps each spelling to one stored colour over all
        // 38 218 label decorations, and `<Font>` to one stored font, with the
        // 375 that name a configuration style item storing exactly the
        // `{7,2,0,{0,<uuid>},1,100}` `format_native_font` writes.
        let font = native_item_font(item, source)?;
        let payload = native_decoration_payload(item, main_attribute_class, source)?;
        let record = native::format_decoration_item(&native::NativeDecorationItem {
            id: &item.id,
            kind: u8::from(item.tag == "PictureDecoration"),
            name: &item.name,
            text_color: &text_color,
            font: &font,
            payload: &payload,
            title: &title,
            tooltip_title: &tooltip_title,
            width: item.width.as_deref(),
            height: item.height.as_deref(),
            horizontal_stretch: native_flag(item.horizontal_stretch),
            vertical_stretch: native_flag(item.vertical_stretch),
            content: &format!("{{1,{title},0}}"),
            enabled: item.enabled.unwrap_or(true),
            context_menu: Some(&menu),
            visible: item.visible.unwrap_or(true),
            skip_on_input: native_flag(item.skip_on_input),
            tooltip_representation: item.tooltip_representation.map(native_tooltip_representation),
            group_horizontal_align: item.group_horizontal_align.map(native_group_horizontal_align),
            group_vertical_align: item.group_vertical_align.map(native_vertical_align_spelling),
            extended_tooltip: Some(&tooltip),
            auto_max_width: item.auto_max_width.unwrap_or(true),
            max_width: item.max_width.as_deref(),
            auto_max_height: item.auto_max_height.unwrap_or(true),
            max_height: item.max_height.as_deref(),
            ..native::NativeDecorationItem::default()
        })
        .ok_or_else(|| anyhow!("<{}> names something the writer cannot place", item.tag))?;
        return Ok((kind_uuid, record));
    }

    Err(anyhow!("<{}> has no writer yet", item.tag))
}

/// `<Representation>` of a button as the record writer spells it.
const fn native_button_representation(
    representation: FormXmlButtonRepresentation,
) -> &'static str {
    match representation {
        FormXmlButtonRepresentation::Text => "Text",
        FormXmlButtonRepresentation::Picture => "Picture",
        FormXmlButtonRepresentation::PictureAndText => "PictureAndText",
        FormXmlButtonRepresentation::None => "None",
    }
}

/// `<TitleLocation>` as the record writers spell it.
const fn native_title_location(location: FormXmlTitleLocation) -> &'static str {
    match location {
        FormXmlTitleLocation::None => "None",
        FormXmlTitleLocation::Left => "Left",
        FormXmlTitleLocation::Top => "Top",
        FormXmlTitleLocation::Right => "Right",
    }
}

/// The `{0,<align>,<autofill>}` payload every command bar carries.
///
/// Both members were read by the partition test over all 12 506 root bars of
/// the corpus: `<HorizontalAlign>` maps absent to 0, `Center` to 1, `Right` to
/// 2 and `Auto` to 3, and `<Autofill>` writes 0 when the bar turns it off and
/// 1 when it says nothing. `Left` is never stored, so it is refused.
fn native_command_bar_payload(
    horizontal_align: Option<FormXmlHorizontalAlign>,
    autofill: Option<bool>,
) -> Result<String> {
    let align = match horizontal_align {
        None => "0",
        Some(FormXmlHorizontalAlign::Center) => "1",
        Some(FormXmlHorizontalAlign::Right) => "2",
        Some(FormXmlHorizontalAlign::Auto) => "3",
        Some(FormXmlHorizontalAlign::Left) => {
            return Err(anyhow!("a command bar aligned Left is not measured"));
        }
    };
    Ok(format!(
        "{{0,{align},{}}}",
        u8::from(autofill != Some(false))
    ))
}

/// The `{55,…}` record of a `<Table>`.
///
/// Head, keyed property bag, events, the table's own excluded commands,
/// context menu, command bar, columns and tail. The head and the tail were
/// measured earlier; the bag is read here.
#[allow(clippy::too_many_arguments)]
fn format_native_table(
    item: &FormXmlChildItem,
    data_paths: &NativeDataPaths<'_>,
    command_ids: &BTreeMap<String, String>,
    items: &BTreeMap<String, NativeItemTarget>,
    main_attribute_class: &str,
    source: Option<&MetadataSourceContext>,
) -> Result<String> {
    use crate::compiler::bodies::form_native as native;

    if item.picture_present || item.font_present {
        return Err(anyhow!("a table names a picture or a font"));
    }
    if !item.scalars.contains_key("DataPath") && item.data_path.is_none() {
        return Err(anyhow!("a table that binds to nothing is not measured"));
    }
    let data_path = match item.data_path.as_deref() {
        Some(path) => data_paths
            .resolve(path)
            .ok_or_else(|| anyhow!("a table binds to {path}, which the writer cannot place"))?,
        None => "{0}".to_string(),
    };

    // A <ContextMenu> is a child item; a table keeps it in a member of its
    // own, as a field does, and its columns are ordinary records.
    let mut context_menu = None;
    let mut command_bar = None;
    let mut columns = Vec::new();
    // The three additions sit in the tail, not among the columns.
    let mut additions: [Option<&FormXmlChildItem>; 3] = [None, None, None];
    for child in &item.child_items {
        match child.tag.as_str() {
            "ContextMenu" if context_menu.is_none() => context_menu = Some(child),
            "AutoCommandBar" if command_bar.is_none() => command_bar = Some(child),
            "SearchStringAddition" => additions[0] = Some(child),
            "ViewStatusAddition" => additions[1] = Some(child),
            "SearchControlAddition" => additions[2] = Some(child),
            _ => columns.push(child),
        }
    }
    let context_menu = match context_menu {
        Some(menu) => native::format_field_context_menu(&menu.id, &menu.name),
        None => return Err(anyhow!("a table with no context menu is not measured")),
    };
    let command_bar = match command_bar {
        Some(bar) => {
            let payload = native_command_bar_payload(
                bar.horizontal_align,
                bar.autofill,
            )?;
            native::format_group_item(&native::NativeGroupItem {
                id: &bar.id,
                kind: 9,
                name: &bar.name,
                payload: &payload,
                ..native::NativeGroupItem::default()
            })
            .ok_or_else(|| anyhow!("a table's command bar names something unplaceable"))?
        }
        None => return Err(anyhow!("a table with no command bar is not measured")),
    };
    let mut column_records = Vec::new();
    for column in columns {
        column_records.push(format_native_child_item(
            column,
            data_paths,
            command_ids,
            items,
            main_attribute_class,
            source,
        )?);
    }
    let column_records = column_records
        .iter()
        .map(|(uuid, record)| (*uuid, record.clone()))
        .collect::<Vec<_>>();

    let title = format_form_title_value(&item.title);
    let tooltip_title = format_form_title_value(&item.tooltip);
    let extended_tooltip = match &item.extended_tooltip {
        Some(tooltip) => native::format_extended_tooltip(&tooltip.id, &tooltip.name),
        None => return Err(anyhow!("a table with no extended tooltip is not measured")),
    };
    let head = native::format_table_head(&native::NativeTableHead {
        id: &item.id,
        representation: item.table_representation.as_deref(),
        name: &item.name,
        title_location: item.title_location.map(native_title_location),
        title_height: item.scalars.get("TitleHeight").map(String::as_str),
        command_bar_location: item.table_command_bar_location.as_deref(),
        title: &title,
        tooltip_title: &tooltip_title,
        data_path: &data_path,
        autofill: item.autofill.unwrap_or(true),
        enabled: item.enabled.unwrap_or(true),
        read_only: item.read_only.unwrap_or(false),
        default_item: item.default_item.unwrap_or(false),
        change_row_set: native_scalar_flag(item, "ChangeRowSet", true),
        change_row_order: native_scalar_flag(item, "ChangeRowOrder", true),
        width: item.width.as_deref(),
        height: item.height.as_deref(),
        height_in_table_rows: item.height_in_table_rows.as_deref(),
        choice_mode: native_scalar_flag(item, "ChoiceMode", false),
        row_input_mode: item.scalars.get("RowInputMode").map(String::as_str),
        selection_mode: item.scalars.get("SelectionMode").map(String::as_str),
        row_selection_mode: item.row_selection_mode.as_deref(),
        header: native_scalar_flag(item, "Header", true),
        header_height: item.scalars.get("HeaderHeight").map(String::as_str),
        footer: native_scalar_flag(item, "Footer", false),
        footer_height: item.scalars.get("FooterHeight").map(String::as_str),
        horizontal_scroll_bar: item.table_horizontal_scroll_bar.map(|value| match value {
            FormTableHorizontalScrollBar::DontUse => "DontUse",
            FormTableHorizontalScrollBar::UseAlways => "UseAlways",
        }),
        vertical_scroll_bar: item.scalars.get("VerticalScrollBar").map(String::as_str),
        horizontal_lines: native_scalar_flag(item, "HorizontalLines", true),
        vertical_lines: native_scalar_flag(item, "VerticalLines", true),
        use_alternation_row_color: item.use_alternation_row_color.unwrap_or(true),
        auto_insert_new_row: native_scalar_flag(item, "AutoInsertNewRow", false),
        initial_list_view: item.table_initial_list_view.map(|value| match value {
            FormTableInitialListView::Beginning => "Beginning",
            FormTableInitialListView::End => "End",
        }),
        initial_tree_view: item.initial_tree_view.as_deref(),
        output: item.scalars.get("Output").map(String::as_str),
        horizontal_stretch: item.horizontal_stretch.unwrap_or(true),
        vertical_stretch: item.vertical_stretch.unwrap_or(true),
        enable_start_drag: item.enable_start_drag.unwrap_or(true),
        enable_drag: item.enable_drag.unwrap_or(true),
        ..native::NativeTableHead::default()
    })
    .ok_or_else(|| anyhow!("<Table> names a spelling the head writer cannot place"))?;

    let mut addition_records = Vec::new();
    for (kind, child) in additions.iter().enumerate() {
        let Some(child) = child else {
            return Err(anyhow!("a table without all three additions is not measured"));
        };
        addition_records.push(native_table_addition(child, kind as u8, items, source)?);
    }

    let tail = native::format_table_tail(&native::NativeTableTail {
        additions: [
            &addition_records[0],
            &addition_records[1],
            &addition_records[2],
        ],
        auto_mark_incomplete: item.auto_mark_incomplete,
        visible: item.visible.unwrap_or(true),
        multiple_choice: item.table_multiple_choice.unwrap_or(false),
        skip_on_input: item.skip_on_input,
        search_on_input: item.table_search_on_input.map(|value| match value {
            FormTableSearchOnInput::Use => "Use",
            FormTableSearchOnInput::DontUse => "DontUse",
        }),
        tooltip_representation: item.tooltip_representation.map(|value| match value {
            FormTooltipRepresentation::Omit => "Auto",
            FormTooltipRepresentation::None => "None",
            FormTooltipRepresentation::Balloon => "Balloon",
            FormTooltipRepresentation::Button => "Button",
            FormTooltipRepresentation::ShowAuto => "ShowAuto",
            FormTooltipRepresentation::ShowTop => "ShowTop",
            FormTooltipRepresentation::ShowLeft => "ShowLeft",
            FormTooltipRepresentation::ShowBottom => "ShowBottom",
            FormTooltipRepresentation::ShowRight => "ShowRight",
        }),
        extended_tooltip: &extended_tooltip,
        search_string_location: item.scalars.get("SearchStringLocation").map(String::as_str),
        view_status_location: item.scalars.get("ViewStatusLocation").map(String::as_str),
        search_control_location: item.scalars.get("SearchControlLocation").map(String::as_str),
        refresh_request: item.scalars.get("RefreshRequest").map(String::as_str),
        auto_max_width: item.auto_max_width.unwrap_or(true),
        max_width: item.max_width.as_deref(),
        auto_max_height: item.auto_max_height.unwrap_or(true),
        max_height: item.max_height.as_deref(),
        height_control_variant: item.scalars.get("HeightControlVariant").map(String::as_str),
        auto_max_rows_count: native_scalar_flag(item, "AutoMaxRowsCount", true),
        max_rows_count: item.scalars.get("MaxRowsCount").map(String::as_str),
        current_row_use: item.table_current_row_use.map(|_| "DontUse"),
        file_drag_mode: item.file_drag_mode.as_deref(),
        ..native::NativeTableTail::default()
    })
    .ok_or_else(|| anyhow!("<Table> names a spelling the tail writer cannot place"))?;

    let bag = native_table_property_bag(item, items, source)?;
    let events = item
        .events
        .iter()
        .map(|event| native::NativeEvent {
            name: &event.name,
            handler: &event.handler,
        })
        .collect::<Vec<_>>();
    let events = native::format_native_events(&item.tag, main_attribute_class, &events)
        .ok_or_else(|| anyhow!("a table names an event the writer cannot place"))?;

    Ok(native::format_table_record(
        &head,
        &bag.iter()
            .map(|(key, value)| (*key, value.clone()))
            .collect::<Vec<_>>(),
        &events,
        &context_menu,
        &command_bar,
        &column_records,
        &tail,
    ))
}

/// The keyed property bag of the form's `{50,…}` root record.
///
/// Which keys a form carries is decided by the class of its main attribute,
/// the same rule the `{55,…}` table bag follows. Measured over all 12 507
/// root records of ERP УХ: 6 966 carry an empty bag, 5 541 carry something,
/// and the twenty-four keys below rebuild from the source with **no misses**
/// over every record that carries them.
///
/// A report form is refused. Its bag holds eleven more keys -- the
/// configuration's four default report forms, the default variant name, a
/// whole composition-settings value and the name of the report the form was
/// developed from -- and nothing in `Form.xml` decides any of them. The name
/// alone disagrees with the main attribute in 26 of 207 forms, so it cannot
/// be derived.
///
/// Keys 25 and 26 are constants that only 829 of 2 207 object forms carry,
/// and no property says which. They are omitted, which is what the majority
/// of the corpus does and what the export reads back either way.
fn native_root_property_bag(
    properties: &FormXmlBodyProperties,
    items: &BTreeMap<String, NativeItemTarget>,
    main_attribute_class: &str,
) -> Result<Vec<(&'static str, String)>> {
    // The id of the item a property names, 0 when it names none -- the same
    // shape the table bag's `<UserSettingsGroup>` carries.
    let item_id = |name: Option<&str>| -> Result<String> {
        let Some(name) = name else {
            return Ok("0".to_string());
        };
        if let Some(target) = items.get(name) {
            return Ok(target.id.clone());
        }
        match name.split_once(':') {
            Some((id, _)) if id.chars().all(|c| c.is_ascii_digit()) => Ok(id.to_string()),
            _ => Err(anyhow!(
                "the form settles into {name}, which it does not declare"
            )),
        }
    };
    let mut bag: Vec<(&'static str, String)> = Vec::new();
    match main_attribute_class {
        "cfg:DynamicList" => {
            bag.push((
                "1",
                format!(
                    "{{\"N\",{}}}",
                    item_id(properties.group_list.as_deref())?
                ),
            ));
        }
        "cfg:DocumentObject" => {
            let auto_time = match properties.auto_time {
                Some(FormXmlAutoTime::DontUse) => "0",
                Some(FormXmlAutoTime::CurrentOrLast) | None => "3",
            };
            let posting = match properties.use_posting_mode {
                Some(FormXmlUsePostingMode::Regular) => "0",
                Some(FormXmlUsePostingMode::Auto) | None => "3",
            };
            bag.push((
                "2",
                format!("{{\"#\",adeb08a0-415c-11d6-b9d1-0050bae0a95d,{auto_time}}}"),
            ));
            bag.push((
                "3",
                format!("{{\"#\",20d89b09-bd04-4304-a8c7-4d07fac6338a,{posting}}}"),
            ));
            bag.push((
                "4",
                format!(
                    "{{\"B\",{}}}",
                    u8::from(properties.repost_on_write.unwrap_or(true))
                ),
            ));
            bag.push(("24", "{\"B\",0}".to_string()));
            bag.push(("25", "{\"U\"}".to_string()));
            bag.push(("26", "{\"B\",1}".to_string()));
        }
        "cfg:CatalogObject" | "cfg:ChartOfCharacteristicTypesObject" => {
            if let Some(folders) = properties.use_for_folders_and_items {
                let code = match folders {
                    FormXmlUseForFoldersAndItems::Items => "0",
                    FormXmlUseForFoldersAndItems::Folders => "1",
                    FormXmlUseForFoldersAndItems::FoldersAndItems => {
                        return Err(anyhow!(
                            "<UseForFoldersAndItems>FoldersAndItems</UseForFoldersAndItems> is not measured"
                        ));
                    }
                };
                bag.push((
                    "0",
                    format!("{{\"#\",59ef2b80-c86b-11d5-a3c1-0050bae0a776,{code}}}"),
                ));
            }
            bag.push(("24", "{\"B\",0}".to_string()));
            bag.push(("25", "{\"U\"}".to_string()));
            bag.push(("26", "{\"B\",1}".to_string()));
        }
        "cfg:TaskObject"
        | "cfg:ExchangePlanObject"
        | "cfg:BusinessProcessObject"
        | "cfg:ChartOfAccountsObject"
        | "cfg:ChartOfCalculationTypesObject" => {
            bag.push(("24", "{\"B\",0}".to_string()));
        }
        "cfg:ReportObject" => {
            return Err(anyhow!(
                "a report form's property bag names what the source does not carry"
            ));
        }
        "dcsset:SettingsComposer" => {
            return Err(anyhow!("a settings-composer form's property bag is not measured"));
        }
        ""
        | "cfg:DataProcessorObject"
        | "cfg:InformationRegisterRecordManager"
        | "cfg:InformationRegisterRecordSet"
        | "cfg:AccountingRegisterRecordSet"
        | "cfg:AccumulationRegisterRecordSet"
        | "cfg:CalculationRegisterRecordSet"
        | "cfg:ConstantsSet"
        | "xs:string" => {}
        other => {
            return Err(anyhow!(
                "a form whose main attribute is {other} has no measured property bag"
            ));
        }
    }
    Ok(bag)
}

/// One of the three `{5,…}` additions a table carries in its tail.
fn native_table_addition(
    item: &FormXmlChildItem,
    kind: u8,
    items: &BTreeMap<String, NativeItemTarget>,
    source: Option<&MetadataSourceContext>,
) -> Result<String> {
    use crate::compiler::bodies::form_native as native;
    let _ = source;

    let mut context_menu = None;
    let mut children = 0usize;
    for child in &item.child_items {
        match child.tag.as_str() {
            "ContextMenu" if context_menu.is_none() => context_menu = Some(child),
            _ => children += 1,
        }
    }
    if children > 0 {
        return Err(anyhow!("an addition with children is not measured"));
    }
    let context_menu = match context_menu {
        Some(menu) => native::format_field_context_menu(&menu.id, &menu.name),
        None => return Err(anyhow!("an addition with no context menu is not measured")),
    };
    let extended_tooltip = match &item.extended_tooltip {
        Some(tooltip) => native::format_extended_tooltip(&tooltip.id, &tooltip.name),
        None => return Err(anyhow!("an addition with no extended tooltip is not measured")),
    };
    // Member 19 names the item the addition serves, which is not always the
    // table it sits in: 392 of the corpus's additions live elsewhere.
    let source_item = match item.addition_source_item.as_deref() {
        Some(name) => match items.get(name) {
            Some(target) => target.id.clone(),
            None => {
                return Err(anyhow!(
                    "an addition serves {name}, which the form does not declare"
                ));
            }
        },
        None => return Err(anyhow!("an addition with no <AdditionSource> is not measured")),
    };

    let auto_max_width = item.auto_max_width.unwrap_or(true);
    let payload = match kind {
        0 => native::format_search_string_addition_payload(
            item.width.as_deref().unwrap_or("0"),
            item.horizontal_stretch,
            auto_max_width,
            item.max_width.as_deref().unwrap_or("0"),
        ),
        1 => native::format_view_status_addition_payload(
            item.scalars.get("HorizontalLocation").map(String::as_str),
            auto_max_width,
        )
        .ok_or_else(|| anyhow!("a view status addition names an unmeasured location"))?,
        _ => native::format_search_control_addition_payload(auto_max_width),
    };

    native::format_table_addition(&native::NativeTableAddition {
        id: &item.id,
        kind,
        name: &item.name,
        title: &format_form_title_value(&item.title),
        tooltip_title: &format_form_title_value(&item.tooltip),
        visible: item.visible.unwrap_or(true),
        enabled: item.enabled.unwrap_or(true),
        tooltip_representation: item.tooltip_representation.map(|value| match value {
            FormTooltipRepresentation::Omit => "Auto",
            FormTooltipRepresentation::None => "None",
            FormTooltipRepresentation::Balloon => "Balloon",
            FormTooltipRepresentation::Button => "Button",
            FormTooltipRepresentation::ShowAuto => "ShowAuto",
            FormTooltipRepresentation::ShowTop => "ShowTop",
            FormTooltipRepresentation::ShowLeft => "ShowLeft",
            FormTooltipRepresentation::ShowBottom => "ShowBottom",
            FormTooltipRepresentation::ShowRight => "ShowRight",
        }),
        payload: &payload,
        context_menu: &context_menu,
        extended_tooltip: &extended_tooltip,
        source_item: &source_item,
        group_horizontal_align: item.scalars.get("GroupHorizontalAlign").map(String::as_str),
        display_importance: item.display_importance.as_deref(),
    })
    .ok_or_else(|| anyhow!("an addition names a spelling the writer cannot place"))
}

/// The keyed property bag of a `{55,…}` table record.
///
/// Measured over all 10 738 tables of ERP УХ that split: every key that is not
/// a constant carries one XML property, and each maps every spelling and its
/// absence to exactly one stored value. A table bound to a dynamic list
/// carries the whole set; one bound to anything else carries key 13 when it
/// names a `<RowFilter>`, and key 19.
fn native_table_property_bag(
    item: &FormXmlChildItem,
    items: &BTreeMap<String, NativeItemTarget>,
    source: Option<&MetadataSourceContext>,
) -> Result<Vec<(&'static str, String)>> {
    let _ = source;
    let scalar = |name: &str| item.scalars.get(name).map(String::as_str);
    let flag = |name: &str, default: bool| {
        format!("{{\"B\",{}}}", u8::from(native_scalar_flag(item, name, default)))
    };
    let mut bag = Vec::new();
    let dynamic_list = items.get(&item.name).is_some_and(|target| target.dynamic_list);
    if dynamic_list {
        bag.push(("5", flag("AutoRefresh", false)));
        bag.push((
            "6",
            format!("{{\"N\",{}}}", scalar("AutoRefreshPeriod").unwrap_or("60")),
        ));
        bag.push(("7", "{\"#\",2fdc88ec-7c9b-43cd-8b0d-7d4dbbd0d1b3}".to_string()));
        let folders = match scalar("ChoiceFoldersAndItems") {
            None | Some("Items") => "0",
            Some("Folders") => "1",
            Some("FoldersAndItems") => "2",
            Some(other) => {
                return Err(anyhow!("a table's <ChoiceFoldersAndItems>{other} is not measured"));
            }
        };
        bag.push((
            "8",
            format!("{{\"#\",59ef2b80-c86b-11d5-a3c1-0050bae0a776,{folders}}}"),
        ));
        bag.push(("9", flag("RestoreCurrentRow", false)));
        bag.push(("10", "{\"U\"}".to_string()));
        bag.push(("11", flag("ShowRoot", true)));
        bag.push(("12", flag("AllowRootChoice", false)));
        let update = match scalar("UpdateOnDataChange") {
            None | Some("Auto") => "0",
            Some("DontUpdate") => "1",
            Some(other) => {
                return Err(anyhow!("a table's <UpdateOnDataChange>{other} is not measured"));
            }
        };
        bag.push((
            "14",
            format!("{{\"#\",eac7bfa0-10b4-4369-996c-d258871ad519,{update}}}"),
        ));
        bag.push(("15", "{\"U\"}".to_string()));
        let group = match item.user_settings_group.as_deref() {
            None => "0".to_string(),
            Some(name) => match items.get(name) {
                Some(target) => target.id.clone(),
                // The group is sometimes spelled as `<id>:<namespace>`.
                None => match name.split_once(':') {
                    Some((id, _)) if id.chars().all(|c| c.is_ascii_digit()) => id.to_string(),
                    _ => {
                        return Err(anyhow!(
                            "a table settles into {name}, which the form does not declare"
                        ));
                    }
                },
            },
        };
        bag.push(("16", format!("{{\"N\",{group}}}")));
        bag.push(("19", "{\"S\",\"\"}".to_string()));
        bag.push(("20", flag("AllowGettingCurrentRowURL", true)));
    } else {
        if item.row_filter_present {
            bag.push(("13", "{\"U\"}".to_string()));
        }
        bag.push(("19", "{\"S\",\"\"}".to_string()));
    }
    Ok(bag)
}

/// The payload a container carries, by its tag.
///
/// Fail-closed throughout: a property whose spelling the corpus never stored,
/// and a member no measurement has named, refuse the form rather than take a
/// default that would load wrong.
fn native_container_payload(
    item: &FormXmlChildItem,
    data_paths: &NativeDataPaths<'_>,
    source: Option<&MetadataSourceContext>,
) -> Result<String> {
    use crate::compiler::bodies::form_native as native;
    match item.tag.as_str() {
        "UsualGroup" => {
            if item.format_present {
                return Err(anyhow!("a group names a format"));
            }
            if item.collapsed_representation_title_present {
                return Err(anyhow!("a group names a collapsed-representation title"));
            }
            if item.associated_table_element_id.is_some() {
                return Err(anyhow!("a group names an associated table element"));
            }
            let title_data_path = match item.title_data_path.as_deref() {
                Some(path) => data_paths.resolve(path).ok_or_else(|| {
                    anyhow!("a group titles itself from {path}, which the writer cannot place")
                })?,
                None => "{0}".to_string(),
            };
            let back_color = native_item_color(item.back_color.as_deref(), source)
                .ok_or_else(|| anyhow!("a group names a background colour it cannot place"))?;
            let hidden = native_item_color(item.hidden_state_title_back_color.as_deref(), source)
                .ok_or_else(|| anyhow!("a group names a hidden-state colour it cannot place"))?;
            native::format_usual_group_payload(&native::NativeUsualGroupPayload {
                group: item.group.map(native_group_spelling),
                behavior: item.behavior.map(native_group_behavior_spelling),
                child_items_width: item.child_items_width.as_deref(),
                representation: item.representation.map(native_group_representation_spelling),
                show_title: item.show_title.unwrap_or(true),
                title_data_path: &title_data_path,
                back_color: &back_color,
                control_representation: item.control_representation.as_deref(),
                collapsed: item.collapsed.unwrap_or(false),
                show_left_margin: item.show_left_margin.unwrap_or(true),
                horizontal_spacing: item.horizontal_spacing.as_deref(),
                vertical_spacing: item.vertical_spacing.as_deref(),
                horizontal_align: item.horizontal_align.map(native_horizontal_align_spelling),
                vertical_align: item.vertical_align.map(native_vertical_align_spelling),
                through_align: item.through_align.as_deref(),
                children_align: item.children_align.as_deref(),
                united: item.united.unwrap_or(true),
                hidden_state_title_back_color: &hidden,
                current_row_use: item.current_row_use.as_deref(),
                ..native::NativeUsualGroupPayload::plain()
            })
            .ok_or_else(|| anyhow!("<UsualGroup> names a spelling the writer cannot place"))
        }
        "ButtonGroup" => {
            let command_source = native_command_source(item)?;
            native::format_button_group_payload(
                &command_source,
                item.container_representation.as_deref(),
            )
            .ok_or_else(|| anyhow!("<ButtonGroup> names a spelling the writer cannot place"))
        }
        "CommandBar" => {
            let command_source = native_command_source(item)?;
            native::format_command_bar_payload(
                item.horizontal_align.map(native_horizontal_align_spelling),
                &command_source,
            )
            .ok_or_else(|| anyhow!("<CommandBar> names a spelling the writer cannot place"))
        }
        "Pages" => {
            if item.associated_table_element_id.is_some() {
                return Err(anyhow!("a pages group names an associated table element"));
            }
            native::format_pages_payload(
                item.pages_representation.as_deref(),
                "{0,1,0}",
                "0",
            )
            .ok_or_else(|| anyhow!("<Pages> names a spelling the writer cannot place"))
        }
        "Popup" => {
            if item.picture_present {
                return Err(anyhow!("a popup names a picture"));
            }
            let command_source = native_command_source(item)?;
            let back_color = native_item_color(item.back_color.as_deref(), source)
                .ok_or_else(|| anyhow!("a popup names a background colour it cannot place"))?;
            let border_color = native_item_color(item.popup_border_color.as_deref(), source)
                .ok_or_else(|| anyhow!("a popup names a border colour it cannot place"))?;
            native::format_popup_payload(&native::NativePopupPayload {
                command_source: &command_source,
                representation: item.container_representation.as_deref(),
                shape: item.shape.as_deref(),
                shape_representation: item.shape_representation.as_deref(),
                back_color: &back_color,
                border_color: &border_color,
                ..native::NativePopupPayload::plain()
            })
            .ok_or_else(|| anyhow!("<Popup> names a spelling the writer cannot place"))
        }
        "ColumnGroup" => {
            if item.picture_present {
                return Err(anyhow!("a column group names a picture"));
            }
            let title_back_color = native_item_color(item.title_back_color.as_deref(), source)
                .ok_or_else(|| anyhow!("a column group names a colour it cannot place"))?;
            native::format_column_group_payload(&native::NativeColumnGroupPayload {
                group: item.group.map(native_group_spelling),
                show_title: item.show_title.unwrap_or(true),
                show_in_header: item.show_in_header.unwrap_or(false),
                header_horizontal_align: item.header_horizontal_align.as_deref(),
                title_back_color: &title_back_color,
                fixing_in_table: item.fixing_in_table.map(native_fixing_in_table_spelling),
                ..native::NativeColumnGroupPayload::plain()
            })
            .ok_or_else(|| anyhow!("<ColumnGroup> names a spelling the writer cannot place"))
        }
        "Page" => {
            if item.picture_present {
                return Err(anyhow!("a page names a picture"));
            }
            if item.format_present {
                return Err(anyhow!("a page names a format"));
            }
            let title_data_path = match item.title_data_path.as_deref() {
                Some(path) => data_paths.resolve(path).ok_or_else(|| {
                    anyhow!("a page titles itself from {path}, which the writer cannot place")
                })?,
                None => "{0}".to_string(),
            };
            let back_color = native_item_color(item.back_color.as_deref(), source)
                .ok_or_else(|| anyhow!("a page names a background colour it cannot place"))?;
            native::format_page_payload(&native::NativePagePayload {
                group: item.group.map(native_group_spelling),
                child_items_width: item.child_items_width.as_deref(),
                title_data_path: &title_data_path,
                show_title: item.show_title.unwrap_or(true),
                back_color: &back_color,
                horizontal_spacing: item.horizontal_spacing.as_deref(),
                vertical_spacing: item.vertical_spacing.as_deref(),
                horizontal_align: item.horizontal_align.map(native_horizontal_align_spelling),
                vertical_align: item.vertical_align.map(native_vertical_align_spelling),
                children_align: item.children_align.as_deref(),
                scroll_on_compress: item.scroll_on_compress.unwrap_or(false),
                ..native::NativePagePayload::plain()
            })
            .ok_or_else(|| anyhow!("<Page> names a spelling the writer cannot place"))
        }
        "ContextMenu" => Ok("{1,1}".to_string()),
        _ => Err(anyhow!("<{}> has no payload writer yet", item.tag)),
    }
}

/// What a `<Button>` stores for its `<CommandName>`.
///
/// Always `{<target>,<uuid>}`: the target is 0 for a form standard command
/// and the target item's own id for an item standard command -- true in all
/// 15 692 standard-command buttons of ERP УХ -- and the command's own id for
/// a form command. The uuid is fixed per scope and name, and the tables that
/// carry it were read from the corpus.
fn native_button_command(
    item: &FormXmlChildItem,
    command_ids: &BTreeMap<String, String>,
    items: &BTreeMap<String, NativeItemTarget>,
    main_attribute_class: &str,
) -> Result<String> {
    use crate::compiler::bodies::form_native as native;
    let Some(path) = item.command_name.as_deref() else {
        return Ok("{0}".to_string());
    };
    if let Some(name) = path.strip_prefix("Form.Command.") {
        let id = command_ids
            .get(name)
            .ok_or_else(|| anyhow!("a button runs {path}, which the form does not declare"))?;
        return Ok(format!("{{{id},{}}}", native::FORM_COMMAND_NAMESPACE_UUID));
    }
    if let Some(name) = path.strip_prefix("Form.StandardCommand.") {
        let uuid = native::form_standard_command_uuid(main_attribute_class, name)
            .ok_or_else(|| anyhow!("no measured uuid for {path} on {main_attribute_class}"))?;
        return Ok(format!("{{0,{uuid}}}"));
    }
    if let Some(rest) = path.strip_prefix("Form.Item.")
        && let Some((target, name)) = rest.rsplit_once(".StandardCommand.")
    {
        let target = items
            .get(target)
            .ok_or_else(|| anyhow!("a button runs {path}, whose item the form does not declare"))?;
        let uuid = native::item_standard_command_uuid(&target.tag, target.dynamic_list, name)
            .ok_or_else(|| anyhow!("no measured uuid for {path} on <{}>", target.tag))?;
        return Ok(format!("{{{},{uuid}}}", target.id));
    }
    Err(anyhow!("a button's command names a configuration object"))
}

/// What a standard command needs to know about the item it acts on.
struct NativeItemTarget {
    tag: String,
    id: String,
    /// Whether the item is bound to an attribute of type `cfg:DynamicList`,
    /// which is what tells two uuids of the same command name apart.
    dynamic_list: bool,
}

