fn patch_form_layout_auto_command_bar(
    text: &mut String,
    command_bar: &FormXmlAutoCommandBar,
    commands: &[FormXmlCommand],
    command_uuids: &BTreeMap<String, String>,
    source: Option<&MetadataSourceContext>,
) -> Result<bool> {
    let fields = scan_braced_fields(text, 0)?;
    if fields.first().map(|range| text[range.clone()].trim()) == Some("22")
        && let Some(identity_range) = fields.get(1)
        && let Ok(identity) = scan_braced_fields(text, identity_range.start)
        && identity
            .first()
            .is_some_and(|range| text[range.clone()].trim() == command_bar.id)
        && let Some(name_range) = fields.get(6)
        && parse_1c_quoted_string(&text[name_range.clone()]).is_ok()
    {
        let mut replacements = Vec::<(Range<usize>, String)>::new();
        replacements.push((name_range.clone(), format_1c_string(&command_bar.name)));
        if (command_bar.horizontal_align.is_some() || command_bar.autofill.is_some())
            && let Some(settings_range) = fields.get(20)
            && let Some(settings) = format_form_auto_command_bar_settings(
                &text[settings_range.clone()],
                command_bar.horizontal_align,
                command_bar.autofill,
            )?
        {
            replacements.push((settings_range.clone(), settings));
        }
        replacements.sort_by_key(|(range, _)| range.start);
        for (range, replacement) in replacements.into_iter().rev() {
            text.replace_range(range, &replacement);
        }
        if command_bar.child_items_present {
            retain_form_layout_direct_child_items(text, &command_bar.child_items)?;
        }
        for child in &command_bar.child_items {
            if !is_form_layout_creatable_nested_item(child)
                && !form_child_item_strict_properties_require_existing_layout(child)
            {
                continue;
            }
            let _ = patch_or_append_form_layout_direct_child_item(
                text,
                child,
                commands,
                &BTreeMap::new(),
                &BTreeMap::new(),
                &BTreeMap::new(),
                command_uuids,
                source,
            )?;
        }
        return Ok(true);
    }

    for range in fields {
        if !text[range.clone()].trim_start().starts_with('{') {
            continue;
        }
        let mut nested = text[range.clone()].to_string();
        if patch_form_layout_auto_command_bar(
            &mut nested,
            command_bar,
            commands,
            command_uuids,
            source,
        )? {
            text.replace_range(range, &nested);
            return Ok(true);
        }
    }
    Ok(false)
}

fn format_form_auto_command_bar_settings(
    existing: &str,
    horizontal_align: Option<FormXmlHorizontalAlign>,
    autofill: Option<bool>,
) -> Result<Option<String>> {
    let mut text = existing.trim().to_string();
    let fields = scan_braced_fields(&text, 0)?;
    if fields.len() <= 1 || (autofill.is_some() && fields.len() <= 2) {
        return Ok(None);
    }
    if let Some(horizontal_align) = horizontal_align {
        replace_braced_field(&mut text, 1, form_horizontal_align_code(horizontal_align))?;
    }
    if let Some(autofill) = autofill {
        replace_braced_field(&mut text, 2, if autofill { "1" } else { "0" })?;
    }
    Ok(Some(text))
}

fn form_horizontal_align_code(value: FormXmlHorizontalAlign) -> &'static str {
    match value {
        FormXmlHorizontalAlign::Left => "0",
        FormXmlHorizontalAlign::Center => "1",
        FormXmlHorizontalAlign::Right => "2",
        FormXmlHorizontalAlign::Auto => "3",
    }
}

fn form_command_uuids_for_pack(
    plain: &str,
    commands: &[FormXmlCommand],
) -> Result<BTreeMap<String, String>> {
    let mut uuids = BTreeMap::new();
    let container = FormBodyContainer::parse(plain)?;
    if let Some(commands_range) = container.trailing_ranges.get(2) {
        collect_form_command_uuids(&plain[commands_range.clone()], &mut uuids)?;
    }
    for command in commands {
        let deterministic = deterministic_form_local_uuid("command", &command.id, &command.name);
        uuids.entry(command.name.clone()).or_insert(deterministic);
    }
    Ok(uuids)
}

fn deterministic_form_local_uuid(kind: &str, id: &str, name: &str) -> String {
    let mut hasher = Sha256::new();
    hasher.update(b"ibcmd-rs/form-local-id/v1\0");
    hasher.update(kind.as_bytes());
    hasher.update(b"\0");
    hasher.update(id.as_bytes());
    hasher.update(b"\0");
    hasher.update(name.as_bytes());
    let digest = hasher.finalize();
    let mut bytes = [0_u8; 16];
    bytes.copy_from_slice(&digest[..16]);
    bytes[6] = (bytes[6] & 0x0f) | 0x50;
    bytes[8] = (bytes[8] & 0x3f) | 0x80;
    Uuid::from_bytes(bytes).hyphenated().to_string()
}

fn collect_form_command_uuids(text: &str, uuids: &mut BTreeMap<String, String>) -> Result<()> {
    let fields = scan_braced_fields(text, 0)?;
    if fields.first().map(|range| text[range.clone()].trim()) == Some("11")
        && let Some(name) = fields
            .get(2)
            .and_then(|range| parse_1c_quoted_string(&text[range.clone()]).ok())
        && let Some(uuid) = fields
            .get(1)
            .and_then(|range| scan_braced_fields(text, range.start).ok())
            .and_then(|identity| {
                identity
                    .get(1)
                    .map(|range| text[range.clone()].trim().to_string())
            })
            .filter(|uuid| is_uuid_text(uuid))
    {
        uuids.insert(name, uuid);
        return Ok(());
    }

    for range in fields {
        if !text[range.clone()].trim_start().starts_with('{') {
            continue;
        }
        collect_form_command_uuids(&text[range], uuids)?;
    }
    Ok(())
}

fn patch_form_layout_events(
    layout: &mut String,
    events: &[FormXmlEvent],
    retain_missing: bool,
) -> Result<()> {
    if retain_missing {
        retain_form_layout_events(layout, events)?;
    }
    let mut occurrence_by_name = BTreeMap::<String, usize>::new();
    for event in events {
        let identifiers = form_event_layout_identifiers(&event.name);
        let occurrence = occurrence_by_name.entry(event.name.clone()).or_default();
        let _ = patch_form_layout_event(layout, &identifiers, &event.handler, *occurrence)?;
        *occurrence += 1;
    }
    Ok(())
}

fn retain_form_layout_events(text: &mut String, events: &[FormXmlEvent]) -> Result<()> {
    let keep_identifiers = events
        .iter()
        .map(|event| form_event_layout_identifiers(&event.name))
        .collect::<Vec<_>>();
    let fields = scan_braced_fields(text, 0)?;
    if fields.is_empty() {
        return Ok(());
    }

    let mut retained = Vec::with_capacity(fields.len());
    let mut changed = false;
    for (index, range) in fields.iter().enumerate() {
        let field = text[range.clone()].to_string();
        if index == 0 {
            retained.push(field);
            continue;
        }
        if !field.trim_start().starts_with('{') {
            retained.push(field);
            continue;
        }
        match form_layout_event_entry_name(&field)? {
            Some(name) if !form_layout_event_name_is_kept(&name, &keep_identifiers) => {
                changed = true;
            }
            _ => retained.push(field),
        }
    }
    if !changed {
        return Ok(());
    }

    *text = format!("{{{}}}", retained.join(","));
    Ok(())
}

fn form_layout_event_entry_name(text: &str) -> Result<Option<String>> {
    let fields = scan_braced_fields(text, 0)?;
    if fields.len() < 3 {
        return Ok(None);
    }
    if parse_1c_quoted_string(&text[fields[2].clone()]).is_err() {
        return Ok(None);
    }
    Ok(fields.get(1).map(|range| {
        parse_1c_quoted_string(&text[range.clone()])
            .unwrap_or_else(|_| text[range.clone()].trim().to_string())
    }))
}

fn form_layout_event_name_is_kept(name: &str, keep_identifiers: &[Vec<&str>]) -> bool {
    keep_identifiers.iter().any(|identifiers| {
        identifiers
            .iter()
            .any(|identifier| name.eq_ignore_ascii_case(identifier))
    })
}

fn patch_form_layout_child_items(
    layout: &mut String,
    items: &[FormXmlChildItem],
    attributes: &[FormXmlAttribute],
    commands: &[FormXmlCommand],
    command_uuids: &BTreeMap<String, String>,
    source: Option<&MetadataSourceContext>,
    retain_missing: bool,
) -> Result<()> {
    if retain_missing {
        retain_form_layout_top_level_child_items(layout, items)?;
    }
    let table_ids_by_name = form_layout_table_ids_by_name(layout)?;
    let table_column_ids_by_name = form_layout_table_column_ids_by_name(layout)?;
    let attribute_ids_by_name = form_attribute_ids_by_name(attributes);
    let item_ids_by_name = form_xml_child_item_ids_by_name(items);
    patch_form_layout_table_user_settings_groups(layout, items, &item_ids_by_name)?;
    for item in items {
        if item.depth != 0 {
            continue;
        }
        let patched = patch_form_layout_child_item(
            layout,
            item,
            commands,
            &attribute_ids_by_name,
            &table_ids_by_name,
            &table_column_ids_by_name,
            command_uuids,
            source,
        )
        .with_context(|| format!("failed to patch Form layout child item {}", item.name))?;
        if !patched {
            let _ = append_form_layout_top_level_child_item(
                layout,
                item,
                commands,
                &attribute_ids_by_name,
                &table_ids_by_name,
                &table_column_ids_by_name,
                command_uuids,
                source,
            )
            .with_context(|| format!("failed to append Form layout child item {}", item.name))?;
        }
    }
    Ok(())
}

fn patch_form_layout_table_user_settings_groups(
    layout: &mut String,
    items: &[FormXmlChildItem],
    item_ids_by_name: &BTreeMap<String, String>,
) -> Result<()> {
    for item in items {
        if let Some(group_id) = item
            .user_settings_group
            .as_ref()
            .and_then(|name| item_ids_by_name.get(name))
        {
            let _ = patch_form_layout_table_user_settings_group(layout, item, group_id)
                .with_context(|| {
                    format!(
                        "failed to patch Form Table UserSettingsGroup for {}",
                        item.name
                    )
                })?;
        }
        patch_form_layout_table_user_settings_groups(layout, &item.child_items, item_ids_by_name)?;
    }
    Ok(())
}

fn form_attribute_ids_by_name(attributes: &[FormXmlAttribute]) -> BTreeMap<String, String> {
    attributes
        .iter()
        .map(|attribute| (attribute.name.clone(), attribute.id.clone()))
        .collect()
}

fn form_xml_child_item_ids_by_name(items: &[FormXmlChildItem]) -> BTreeMap<String, String> {
    let mut ids = BTreeMap::new();
    collect_form_xml_child_item_ids_by_name(items, &mut ids);
    ids
}

fn collect_form_xml_child_item_ids_by_name(
    items: &[FormXmlChildItem],
    ids: &mut BTreeMap<String, String>,
) {
    for item in items {
        ids.insert(item.name.clone(), item.id.clone());
        collect_form_xml_child_item_ids_by_name(&item.child_items, ids);
    }
}

fn patch_form_layout_table_user_settings_group(
    text: &mut String,
    item: &FormXmlChildItem,
    group_id: &str,
) -> Result<bool> {
    let fields = scan_braced_fields(text, 0)?;
    if form_layout_child_item_matches(text, &fields, item) && item.tag == "Table" {
        if let Some(value_range) = form_layout_table_property_bag_value_range(
            text,
            &fields,
            TableBagKey::UserSettingsGroup,
        ) && is_form_property_bag_number_value(&text[value_range.clone()])
        {
            text.replace_range(value_range, &format!(r#"{{"N",{group_id}}}"#));
            return Ok(true);
        }
        return Ok(false);
    }

    for range in fields {
        if !text[range.clone()].trim_start().starts_with('{') {
            continue;
        }
        let mut nested = text[range.clone()].to_string();
        if patch_form_layout_table_user_settings_group(&mut nested, item, group_id)? {
            text.replace_range(range, &nested);
            return Ok(true);
        }
    }
    Ok(false)
}

fn retain_form_layout_top_level_child_items(
    text: &mut String,
    items: &[FormXmlChildItem],
) -> Result<()> {
    let fields = scan_braced_fields(text, 0)?;
    let Some(span) = form_layout_root_child_items_span(text, &fields) else {
        return Ok(());
    };

    let top_level_items = items
        .iter()
        .filter(|item| item.depth == 0)
        .collect::<Vec<_>>();
    let mut retained = Vec::<(String, String)>::new();
    let mut changed = false;

    for index in 0..span.count {
        let uuid_range = fields[span.first_uuid_index + index * 2].clone();
        let item_range = fields[span.first_uuid_index + 1 + index * 2].clone();
        let uuid = text[uuid_range].trim().to_string();
        if !is_uuid_text(&uuid) {
            return Ok(());
        }
        let item_text = text[item_range].to_string();
        let item_fields = scan_braced_fields(&item_text, 0)?;
        let is_known_item = item_fields
            .first()
            .and_then(|range| {
                form_layout_child_item_tag(
                    item_text[range.clone()].trim(),
                    &item_text,
                    &item_fields,
                )
            })
            .is_some();
        let keep = !is_known_item
            || top_level_items
                .iter()
                .any(|item| form_layout_child_item_matches(&item_text, &item_fields, item));
        if keep {
            retained.push((uuid, item_text));
        } else {
            changed = true;
        }
    }

    if !changed {
        return Ok(());
    }

    let replace_end = if span.count == 0 {
        span.count_range.end
    } else {
        fields[span.first_uuid_index - 1 + span.count * 2].end
    };
    let mut replacement = retained.len().to_string();
    for (uuid, item_text) in retained {
        replacement.push(',');
        replacement.push_str(&uuid);
        replacement.push(',');
        replacement.push_str(&item_text);
    }
    text.replace_range(span.count_range.start..replace_end, &replacement);
    Ok(())
}

fn patch_form_layout_child_item(
    text: &mut String,
    item: &FormXmlChildItem,
    commands: &[FormXmlCommand],
    attribute_ids_by_name: &BTreeMap<String, String>,
    table_ids_by_name: &BTreeMap<String, String>,
    table_column_ids_by_name: &BTreeMap<(String, String), String>,
    command_uuids: &BTreeMap<String, String>,
    source: Option<&MetadataSourceContext>,
) -> Result<bool> {
    let fields = scan_braced_fields(text, 0)?;
    if form_layout_child_item_matches(text, &fields, item) {
        patch_form_layout_child_item_entry(
            text,
            &fields,
            item,
            commands,
            attribute_ids_by_name,
            table_ids_by_name,
            table_column_ids_by_name,
            command_uuids,
            source,
        )
        .with_context(|| format!("failed to patch Form layout child item entry {}", item.name))?;
        return Ok(true);
    }

    for range in fields {
        if !text[range.clone()].trim_start().starts_with('{') {
            continue;
        }
        let mut nested = text[range.clone()].to_string();
        if patch_form_layout_child_item(
            &mut nested,
            item,
            commands,
            attribute_ids_by_name,
            table_ids_by_name,
            table_column_ids_by_name,
            command_uuids,
            source,
        )? {
            text.replace_range(range, &nested);
            return Ok(true);
        }
    }
    Ok(false)
}

fn append_form_layout_top_level_child_item(
    text: &mut String,
    item: &FormXmlChildItem,
    commands: &[FormXmlCommand],
    attribute_ids_by_name: &BTreeMap<String, String>,
    table_ids_by_name: &BTreeMap<String, String>,
    table_column_ids_by_name: &BTreeMap<(String, String), String>,
    command_uuids: &BTreeMap<String, String>,
    source: Option<&MetadataSourceContext>,
) -> Result<bool> {
    if item.depth != 0 {
        return Ok(false);
    }
    if form_child_item_strict_properties_require_existing_layout(item) {
        return Err(anyhow!(
            "cannot create Form child item {} with strict-schema properties without an existing strict layout",
            item.name
        ));
    }
    if !is_form_layout_creatable_top_level_item(item) {
        return Ok(false);
    }
    let fields = scan_braced_fields(text, 0)?;
    let Some(span) = form_layout_root_child_items_span(text, &fields) else {
        return Ok(false);
    };

    let item_uuid = deterministic_form_local_uuid("item", &item.id, &item.name);
    let item_text = format_form_layout_new_top_level_item(
        item,
        &item_uuid,
        commands,
        attribute_ids_by_name,
        table_ids_by_name,
        table_column_ids_by_name,
        command_uuids,
        source,
    )?;
    let insert_at = if span.count == 0 {
        span.count_range.end
    } else {
        fields
            .get(span.first_uuid_index - 1 + span.count * 2)
            .map(|range| range.end)
            .ok_or_else(|| anyhow!("Form layout root child span is truncated"))?
    };
    text.insert_str(insert_at, &format!(",{item_uuid},{item_text}"));
    text.replace_range(span.count_range, &(span.count + 1).to_string());
    Ok(true)
}

fn form_layout_root_child_items_span(
    text: &str,
    fields: &[Range<usize>],
) -> Option<FormLayoutDirectChildItemsSpan> {
    let marker = fields.first().map(|range| text[range.clone()].trim())?;
    if marker == "59" {
        return form_layout_direct_child_items_span_at(text, fields, 1, 2);
    }
    if marker != "50" {
        return None;
    }

    const ROOT_TRAILER_FIELDS: usize = 24;
    let tail_start = fields.len().checked_sub(ROOT_TRAILER_FIELDS)?;
    let max_count = tail_start.saturating_sub(1).div_euclid(2).min(200);
    let mut matched = None;
    for count in 0..=max_count {
        let count_index = tail_start.checked_sub(1 + count * 2)?;
        if text[fields.get(count_index)?.clone()]
            .trim()
            .parse::<usize>()
            .ok()
            != Some(count)
        {
            continue;
        }
        let Some(span) =
            form_layout_direct_child_items_span_at(text, fields, count_index, count_index + 1)
        else {
            continue;
        };
        if matched.replace(span).is_some() {
            return None;
        }
    }
    matched
}

fn is_form_layout_creatable_top_level_item(item: &FormXmlChildItem) -> bool {
    matches!(
        item.tag.as_str(),
        "Button"
            | "CommandBar"
            | "AutoCommandBar"
            | "UsualGroup"
            | "ColumnGroup"
            | "Popup"
            | "Pages"
            | "Page"
            | "ButtonGroup"
            | "ContextMenu"
            | "Table"
            | "InputField"
            | "LabelField"
            | "CheckBoxField"
            | "TextDocumentField"
            | "PictureDecoration"
            | "SearchStringAddition"
            | "ViewStatusAddition"
            | "SearchControlAddition"
    )
}

fn form_child_item_strict_properties_require_existing_layout(item: &FormXmlChildItem) -> bool {
    (FormFieldSchema::supports_item_tag(&item.tag)
        && (item.group_horizontal_align.is_some()
            || item.vertical_align.is_some()
            || item.group_vertical_align.is_some()
            || item.fixing_in_table.is_some()
            || (matches!(item.tag.as_str(), "InputField" | "LabelField")
                && item.show_in_footer.is_some())
            || (item.tag == "InputField" && item.choice_folders_and_items.is_some())
            || (item.tag == "CheckBoxField" && item.three_state.is_some())))
        || (item.tag == "Table"
            && (item.table_search_on_input.is_some()
                || item.table_initial_list_view.is_some()
                || item.initial_tree_view.is_some()
                || item.choice_folders_and_items.is_some()))
        || (item.tag == "ColumnGroup" && item.fixing_in_table.is_some())
}

fn format_form_layout_new_top_level_item(
    item: &FormXmlChildItem,
    item_uuid: &str,
    commands: &[FormXmlCommand],
    attribute_ids_by_name: &BTreeMap<String, String>,
    table_ids_by_name: &BTreeMap<String, String>,
    table_column_ids_by_name: &BTreeMap<(String, String), String>,
    command_uuids: &BTreeMap<String, String>,
    source: Option<&MetadataSourceContext>,
) -> Result<String> {
    match item.tag.as_str() {
        "Button" => format_form_layout_new_child_item(
            item,
            item_uuid,
            commands,
            attribute_ids_by_name,
            table_ids_by_name,
            table_column_ids_by_name,
            command_uuids,
            source,
        ),
        "CommandBar" | "AutoCommandBar" | "UsualGroup" | "ColumnGroup" | "Popup" | "Pages"
        | "Page" | "ButtonGroup" | "ContextMenu" => format_form_layout_new_child_item(
            item,
            item_uuid,
            commands,
            attribute_ids_by_name,
            table_ids_by_name,
            table_column_ids_by_name,
            command_uuids,
            source,
        ),
        "Table" => format_form_layout_new_child_item(
            item,
            item_uuid,
            commands,
            attribute_ids_by_name,
            table_ids_by_name,
            table_column_ids_by_name,
            command_uuids,
            source,
        ),
        "InputField"
        | "LabelField"
        | "CheckBoxField"
        | "TextDocumentField"
        | "PictureDecoration"
        | "SearchStringAddition"
        | "ViewStatusAddition"
        | "SearchControlAddition" => format_form_layout_new_child_item(
            item,
            item_uuid,
            commands,
            attribute_ids_by_name,
            table_ids_by_name,
            table_column_ids_by_name,
            command_uuids,
            source,
        ),
        _ => Ok(String::new()),
    }
}

fn format_form_layout_new_child_item(
    item: &FormXmlChildItem,
    item_uuid: &str,
    commands: &[FormXmlCommand],
    attribute_ids_by_name: &BTreeMap<String, String>,
    table_ids_by_name: &BTreeMap<String, String>,
    table_column_ids_by_name: &BTreeMap<(String, String), String>,
    command_uuids: &BTreeMap<String, String>,
    source: Option<&MetadataSourceContext>,
) -> Result<String> {
    if form_child_item_strict_properties_require_existing_layout(item) {
        return Err(anyhow!(
            "cannot create Form child item {} with strict-schema properties without an existing strict layout",
            item.name
        ));
    }
    match item.tag.as_str() {
        "Button" => format_form_layout_new_button_item(
            item,
            item_uuid,
            commands,
            table_ids_by_name,
            table_column_ids_by_name,
            command_uuids,
            source,
        ),
        "CommandBar" | "AutoCommandBar" | "UsualGroup" | "ColumnGroup" | "Popup" | "Pages"
        | "Page" | "ButtonGroup" | "ContextMenu" => format_form_layout_new_group_item(
            item,
            item_uuid,
            commands,
            attribute_ids_by_name,
            table_ids_by_name,
            table_column_ids_by_name,
            command_uuids,
            source,
        ),
        "Table" => format_form_layout_new_table_item(
            item,
            item_uuid,
            commands,
            attribute_ids_by_name,
            table_ids_by_name,
            table_column_ids_by_name,
            command_uuids,
            source,
        ),
        "InputField" => Ok(format_form_layout_new_input_field_item(
            item,
            item_uuid,
            attribute_ids_by_name,
        )),
        "LabelField" => Ok(format_form_layout_new_label_field_item(item, item_uuid)),
        "CheckBoxField" => Ok(format_form_layout_new_checkbox_field_item(item, item_uuid)),
        "TextDocumentField" => Ok(format_form_layout_new_text_document_field_item(
            item,
            item_uuid,
            attribute_ids_by_name,
        )),
        "PictureDecoration" => Ok(format_form_layout_new_picture_decoration_item(
            item, item_uuid,
        )),
        "SearchStringAddition" | "ViewStatusAddition" | "SearchControlAddition" => Ok(
            format_form_layout_new_search_addition_item(item, item_uuid, table_ids_by_name),
        ),
        _ => Ok(String::new()),
    }
}

fn format_form_layout_new_button_item(
    item: &FormXmlChildItem,
    item_uuid: &str,
    commands: &[FormXmlCommand],
    table_ids_by_name: &BTreeMap<String, String>,
    table_column_ids_by_name: &BTreeMap<(String, String), String>,
    command_uuids: &BTreeMap<String, String>,
    source: Option<&MetadataSourceContext>,
) -> Result<String> {
    if item.location_in_command_bar.is_some()
        || item.show_title.is_some()
        || item.default_button.is_some()
    {
        return format_form_layout_new_extended_button_item(
            item,
            item_uuid,
            commands,
            table_ids_by_name,
            table_column_ids_by_name,
            command_uuids,
            source,
        );
    }

    let item_type = item
        .item_type
        .as_deref()
        .and_then(form_button_type_code)
        .unwrap_or("0");
    let command_ref = item
        .command_name
        .as_deref()
        .map(|command_name| {
            format_form_new_button_command_reference(command_name, commands, command_uuids, source)
        })
        .transpose()?
        .flatten()
        .unwrap_or_else(|| "{0}".to_string());
    let data_path_ref = item
        .data_path
        .as_deref()
        .and_then(|data_path| {
            format_form_button_data_path(data_path, table_ids_by_name, table_column_ids_by_name)
        })
        .unwrap_or_else(|| "{0}".to_string());

    let mut text = format!(
        "{{34,{{{},{}}},0,0,0,{},{},{},{},{}",
        item.id,
        item_uuid,
        format_1c_string(&item.name),
        format_1c_synonyms(&item.title),
        item_type,
        command_ref,
        data_path_ref
    );
    text.push_str(&format_form_layout_events_tail(&item.events));
    text.push('}');
    Ok(text)
}

