fn form_layout_table_file_drag_mode_replacement(
    text: &str,
    fields: &[Range<usize>],
    value: &str,
) -> Option<(Range<usize>, String)> {
    if let Some(slot) = form_layout_table_raw_slot(text, fields, |schema, normalized_fields| {
        schema.file_drag_mode_slot(normalized_fields)
    }) {
        let range = fields.get(slot)?.clone();
        let code = FormTableSchema.file_drag_mode_raw_code(value)?;
        return Some((range, code.to_string()));
    }
    let range = fields.get(30)?.clone();
    let code = form_table_file_drag_mode_code(value)?;
    Some((range, code.to_string()))
}

fn patch_form_layout_child_item_entry(
    text: &mut String,
    fields: &[Range<usize>],
    item: &FormXmlChildItem,
    commands: &[FormXmlCommand],
    attribute_ids_by_name: &BTreeMap<String, String>,
    table_ids_by_name: &BTreeMap<String, String>,
    table_column_ids_by_name: &BTreeMap<(String, String), String>,
    command_uuids: &BTreeMap<String, String>,
    source: Option<&MetadataSourceContext>,
) -> Result<()> {
    let Some(wrapper) = fields.first().map(|range| text[range.clone()].trim()) else {
        return Ok(());
    };
    let mut replacements = Vec::<(Range<usize>, String)>::new();
    if let Some(name_range) = form_layout_child_item_name_range(text, wrapper, fields)
        && parse_1c_quoted_string(&text[name_range.clone()]).is_ok()
    {
        replacements.push((name_range, format_1c_string(&item.name)));
    }
    if !item.title.is_empty()
        && let Some(title_range) = form_layout_child_item_title_range(text, wrapper, fields)
        && let Some(replacement) =
            form_localized_replacement(&text[title_range.clone()], &item.title)
    {
        replacements.push((title_range, replacement));
    }
    if !item.tooltip.is_empty()
        && let Some(tooltip_range) = form_layout_child_item_tooltip_range(text, wrapper, fields)
        && let Some(replacement) =
            form_localized_replacement(&text[tooltip_range.clone()], &item.tooltip)
    {
        replacements.push((tooltip_range, replacement));
    }
    if let Some(representation) = item.tooltip_representation
        && let Some(range) =
            form_layout_child_item_tooltip_representation_range(text, fields, item.tag.as_str())
    {
        replacements.push((range, representation.raw_code().to_string()));
    }
    if let Some(vertical_align) = item.vertical_align
        && let Some(range) = form_layout_field_vertical_align_range(text, fields, item.tag.as_str())
    {
        replacements.push((range, vertical_align.raw_code().to_string()));
    }
    if let Some(group_horizontal_align) = item.group_horizontal_align
        && let Some(range) =
            form_layout_field_group_horizontal_align_range(text, fields, item.tag.as_str())
    {
        replacements.push((range, group_horizontal_align.raw_code().to_string()));
    }
    if let Some(group_vertical_align) = item.group_vertical_align
        && let Some(range) =
            form_layout_field_group_vertical_align_range(text, fields, item.tag.as_str())
    {
        replacements.push((range, group_vertical_align.raw_code().to_string()));
    }
    if item.tag != "ColumnGroup"
        && let Some(fixing_in_table) = item.fixing_in_table
    {
        let range = form_layout_field_fixing_in_table_range(text, fields, item.tag.as_str())
            .ok_or_else(|| {
                anyhow!(
                    "Form field FixingInTable requires a supported strict layout for {}",
                    item.name
                )
            })?;
        replacements.push((range, fixing_in_table.field_raw_code().to_string()));
    }
    if let Some(three_state) = item.three_state
        && let Some(range) =
            form_layout_checkbox_field_three_state_range(text, fields, item.tag.as_str())
    {
        replacements.push((range, if three_state { "1" } else { "0" }.to_string()));
    }
    if let Some(representation) = item.warning_on_edit_representation
        && let Some(range) =
            form_layout_field_warning_on_edit_representation_range(text, fields, item.tag.as_str())
    {
        replacements.push((range, representation.raw_code().to_string()));
    }
    if !item.warning_on_edit.is_empty()
        && let Some(range) =
            form_layout_field_warning_on_edit_range(text, fields, item.tag.as_str())
        && let Some(replacement) =
            form_warning_on_edit_replacement(&text[range.clone()], &item.warning_on_edit)
    {
        replacements.push((range, replacement));
    }
    if let Some(style) = item.control_border.as_ref().and_then(|border| border.style)
        && let Some(style_range) = form_layout_control_border_style_range(text, fields, &item.tag)
    {
        replacements.push((style_range, style.raw_code().to_string()));
    }
    if let Some(cell_hyperlink) = item.cell_hyperlink
        && let Some(range) = form_layout_field_cell_hyperlink_range(text, fields, item.tag.as_str())
    {
        replacements.push((range, if cell_hyperlink { "1" } else { "0" }.to_string()));
    }
    if let Some(show_in_footer) = item.show_in_footer
        && let Some(range) = form_layout_field_show_in_footer_range(text, fields, item.tag.as_str())
    {
        replacements.push((range, if show_in_footer { "1" } else { "0" }.to_string()));
    }
    if let Some(hyperlink) = item.hyperlink
        && let Some(range) =
            form_layout_picture_decoration_hyperlink_range(text, fields, item.tag.as_str())
    {
        replacements.push((range, if hyperlink { "1" } else { "0" }.to_string()));
    }
    if let Some(extended_tooltip) = &item.extended_tooltip
        && let Some(tooltip_range) = form_layout_child_item_extended_tooltip_range(text, fields)?
        && let Some(tooltip) = patch_form_layout_child_item_extended_tooltip(
            &text[tooltip_range.clone()],
            extended_tooltip,
        )?
    {
        replacements.push((tooltip_range, tooltip));
    }
    if item.tag == "Table" {
        if let Some(representation) = &item.table_representation
            && let Some(code) = form_table_representation_code(representation)
            && let Some(representation_range) = form_layout_table_representation_range(text, fields)
        {
            replacements.push((representation_range.clone(), code.to_string()));
        }
        if let Some(command_bar_location) = &item.table_command_bar_location
            && let Some(code) = form_table_command_bar_location_code(command_bar_location)
            && let Some(command_bar_range) =
                form_layout_table_command_bar_location_range(text, fields)
        {
            replacements.push((command_bar_range.clone(), code.to_string()));
        }
        if let Some(current_row_use) = item.table_current_row_use
            && let Some(current_row_use_range) =
                form_layout_table_current_row_use_range(text, fields)
        {
            replacements.push((
                current_row_use_range,
                current_row_use.raw_code().to_string(),
            ));
        }
        if let Some(horizontal_scroll_bar) = item.table_horizontal_scroll_bar
            && let Some(horizontal_scroll_bar_range) =
                form_layout_table_horizontal_scroll_bar_range(text, fields)
        {
            replacements.push((
                horizontal_scroll_bar_range,
                horizontal_scroll_bar.raw_code().to_string(),
            ));
        }
        if let Some(multiple_choice) = item.table_multiple_choice
            && let Some(multiple_choice_range) =
                form_layout_table_multiple_choice_range(text, fields)
        {
            replacements.push((
                multiple_choice_range,
                if multiple_choice { "1" } else { "0" }.to_string(),
            ));
        }
        if let Some(search_on_input) = item.table_search_on_input
            && let Some(search_on_input_range) =
                form_layout_table_search_on_input_range(text, fields)
        {
            replacements.push((
                search_on_input_range,
                search_on_input.raw_code().to_string(),
            ));
        }
        if let Some(initial_list_view) = item.table_initial_list_view
            && let Some(initial_list_view_range) =
                form_layout_table_initial_list_view_range(text, fields)
        {
            replacements.push((
                initial_list_view_range,
                initial_list_view.raw_code().to_string(),
            ));
        }
        if let Some(data_path) = &item.data_path
            && let Some(data_path_range) = fields.get(11)
            && text[data_path_range.clone()].trim_start().starts_with('{')
            && let Some(data_path_ref) = form_attribute_data_path_replacement(
                &text[data_path_range.clone()],
                data_path,
                attribute_ids_by_name,
            )
            && !one_c_values_equal_ignoring_ws(&text[data_path_range.clone()], &data_path_ref)
        {
            replacements.push((data_path_range.clone(), data_path_ref));
        }
        if let Some(height) = &item.height_in_table_rows
            && let Some(height_range) = fields.get(21)
        {
            replacements.push((height_range.clone(), height.to_string()));
        }
        if let Some(row_selection_mode) = &item.row_selection_mode
            && let Some(code) = form_table_row_selection_mode_code(row_selection_mode)
            && let Some(row_selection_range) = fields.get(24)
        {
            replacements.push((row_selection_range.clone(), code.to_string()));
        }
        if let Some(enable_start_drag) = item.enable_start_drag
            && let Some(enable_start_drag_range) = fields.get(26)
        {
            replacements.push((
                enable_start_drag_range.clone(),
                if enable_start_drag { "1" } else { "0" }.to_string(),
            ));
        }
        if let Some(enable_drag) = item.enable_drag
            && let Some(enable_drag_range) = fields.get(29)
        {
            replacements.push((
                enable_drag_range.clone(),
                if enable_drag { "1" } else { "0" }.to_string(),
            ));
        }
        if let Some(file_drag_mode) = &item.file_drag_mode
            && let Some(replacement) =
                form_layout_table_file_drag_mode_replacement(text, fields, file_drag_mode)
        {
            replacements.push(replacement);
        }
        if let Some(skip_on_input) = item.skip_on_input
            && let Some(skip_range) = fields.get(12)
        {
            replacements.push((
                skip_range.clone(),
                if skip_on_input { "1" } else { "0" }.to_string(),
            ));
        }
        if let Some(auto_refresh) = item.auto_refresh
            && let Some(auto_refresh_range) =
                form_layout_table_property_bag_value_range(text, fields, TableBagKey::AutoRefresh)
            && is_form_property_bag_bool_value(&text[auto_refresh_range.clone()])
        {
            replacements.push((
                auto_refresh_range.clone(),
                if auto_refresh {
                    r#"{"B",1}"#
                } else {
                    r#"{"B",0}"#
                }
                .to_string(),
            ));
        }
        if let Some(auto_refresh_period) = &item.auto_refresh_period
            && let Some(period_range) = form_layout_table_property_bag_value_range(
                text,
                fields,
                TableBagKey::AutoRefreshPeriod,
            )
            && is_form_property_bag_number_value(&text[period_range.clone()])
        {
            replacements.push((
                period_range.clone(),
                format!(r#"{{"N",{auto_refresh_period}}}"#),
            ));
        }
        if let Some(period) = &item.period
            && let Some(period_range) =
                form_layout_table_property_bag_value_range(text, fields, TableBagKey::Period)
            && is_form_table_period_value(&text[period_range.clone()])
            && let Some(replacement) = format_form_table_period_value(period)
        {
            replacements.push((period_range.clone(), replacement));
        }
        if let Some(use_alternation_row_color) = item.use_alternation_row_color
            && let Some(alternation_range) = form_layout_table_property_bag_value_range(
                text,
                fields,
                TableBagKey::UseAlternationRowColor,
            )
            && is_form_property_bag_bool_value(&text[alternation_range.clone()])
        {
            replacements.push((
                alternation_range.clone(),
                if use_alternation_row_color {
                    r#"{"B",1}"#
                } else {
                    r#"{"B",0}"#
                }
                .to_string(),
            ));
        }
        if let Some(default_item) = item.default_item
            && let Some(default_item_range) =
                form_layout_table_property_bag_value_range(text, fields, TableBagKey::DefaultItem)
            && is_form_property_bag_bool_value(&text[default_item_range.clone()])
        {
            replacements.push((
                default_item_range.clone(),
                if default_item {
                    r#"{"B",1}"#
                } else {
                    r#"{"B",0}"#
                }
                .to_string(),
            ));
        }
        if let Some(initial_tree_view) = &item.initial_tree_view
            && let Some(code) = form_table_initial_tree_view_code(initial_tree_view)
            && let Some(initial_tree_view_range) =
                form_layout_table_initial_tree_view_range(text, fields)
        {
            replacements.push((initial_tree_view_range.clone(), code.to_string()));
        }
        if let Some(choice_folders_and_items) = item.choice_folders_and_items {
            let choice_range = form_layout_table_property_bag_value_range(
                text,
                fields,
                TableBagKey::ChoiceFoldersAndItems,
            )
            .filter(|range| is_form_use_for_folders_and_items_value(&text[range.clone()]))
            .ok_or_else(|| {
                anyhow!(
                    "cannot patch Form Table {} ChoiceFoldersAndItems without an existing strict property-bag value",
                    item.name
                )
            })?;
            replacements.push((
                choice_range,
                format!(
                    r##"{{"#",{FORM_USE_FOR_FOLDERS_AND_ITEMS_UUID},{}}}"##,
                    form_use_for_folders_and_items_code(choice_folders_and_items)
                ),
            ));
        }
        if let Some(restore_current_row) = item.restore_current_row
            && let Some(restore_range) = form_layout_table_property_bag_value_range(
                text,
                fields,
                TableBagKey::RestoreCurrentRow,
            )
            && is_form_property_bag_bool_value(&text[restore_range.clone()])
        {
            replacements.push((
                restore_range.clone(),
                if restore_current_row {
                    r#"{"B",1}"#
                } else {
                    r#"{"B",0}"#
                }
                .to_string(),
            ));
        }
        if item.row_filter_nil == Some(true)
            && let Some(row_filter_range) =
                form_layout_table_property_bag_value_range(text, fields, TableBagKey::RowFilter)
            && is_form_property_bag_undefined_value(&text[row_filter_range.clone()])
        {
            replacements.push((row_filter_range.clone(), r#"{"U"}"#.to_string()));
        }
        if let Some(row_picture_data_path) = &item.row_picture_data_path
            && let Some(row_picture_range) = form_layout_table_property_bag_value_range(
                text,
                fields,
                TableBagKey::RowPictureDataPath,
            )
            && is_form_property_bag_string_value(&text[row_picture_range.clone()])
        {
            replacements.push((
                row_picture_range.clone(),
                format!(r#"{{"S",{}}}"#, format_1c_string(row_picture_data_path)),
            ));
        }
        if let Some(update_on_data_change) = item.update_on_data_change
            && let Some(update_range) = form_layout_table_property_bag_value_range(
                text,
                fields,
                TableBagKey::UpdateOnDataChange,
            )
            && is_form_update_on_data_change_value(&text[update_range.clone()])
        {
            replacements.push((
                update_range.clone(),
                format!(
                    r##"{{"#",{},{}}}"##,
                    FORM_UPDATE_ON_DATA_CHANGE_UUID,
                    form_update_on_data_change_code(update_on_data_change)
                ),
            ));
        }
        if let Some(allow_getting_current_row_url) = item.allow_getting_current_row_url
            && let Some(url_range) = form_layout_table_property_bag_value_range(
                text,
                fields,
                TableBagKey::AllowGettingCurrentRowUrl,
            )
            && is_form_property_bag_bool_value(&text[url_range.clone()])
        {
            replacements.push((
                url_range.clone(),
                if allow_getting_current_row_url {
                    r#"{"B",1}"#
                } else {
                    r#"{"B",0}"#
                }
                .to_string(),
            ));
        }
    }
    if item.tag == "Button"
        && let Some(item_type) = &item.item_type
    {
        if form_layout_button_is_extended(fields) {
            if let Some(type_code) = form_extended_button_type_code(item_type)
                && let Some(type_range) = fields.get(4)
            {
                replacements.push((type_range.clone(), type_code.to_string()));
            }
        } else if let Some(type_code) = form_button_type_code(item_type)
            && let Some(type_range) = fields.get(7)
        {
            replacements.push((type_range.clone(), type_code.to_string()));
        }
    }
    if item.tag == "Button"
        && let Some(representation) = item.button_representation
        && let Some(representation_range) = fields.get(10)
    {
        replacements.push((
            representation_range.clone(),
            form_button_representation_code(representation).to_string(),
        ));
    }
    if item.tag == "Button"
        && let Some(default_button) = item.default_button
        && let Some(default_range) = fields.get(11)
    {
        replacements.push((
            default_range.clone(),
            if default_button { "1" } else { "0" }.to_string(),
        ));
    }
    if matches!(item.tag.as_str(), "InputField" | "TextDocumentField")
        && let Some(read_only) = item.read_only
        && form_layout_input_field_is_extended(fields)
        && let Some(read_only_range) = fields.get(14)
    {
        replacements.push((
            read_only_range.clone(),
            if read_only { "1" } else { "0" }.to_string(),
        ));
    }
    if item.tag == "InputField"
        && let Some(skip_on_input) = item.skip_on_input
        && form_layout_input_field_is_extended(fields)
        && let Some(skip_on_input_range) = fields.get(15)
    {
        replacements.push((
            skip_on_input_range.clone(),
            if skip_on_input { "1" } else { "0" }.to_string(),
        ));
    }
    if item.tag == "Button"
        && let Some(skip_on_input) = item.skip_on_input
        && form_layout_button_is_extended(fields)
        && let Some(skip_on_input_range) = fields.get(29)
    {
        replacements.push((
            skip_on_input_range.clone(),
            if skip_on_input { "1" } else { "0" }.to_string(),
        ));
    }
    if item.tag == "Button"
        && let Some(location) = item.location_in_command_bar
        && form_layout_button_is_extended(fields)
        && let Some(location_range) = fields.get(49)
    {
        replacements.push((
            location_range.clone(),
            form_button_location_in_command_bar_code(location).to_string(),
        ));
    }
    if item.tag == "Button"
        && let Some(show_title) = item.show_title
        && form_layout_button_is_extended(fields)
        && let Some(show_title_range) = fields.get(7)
    {
        replacements.push((
            show_title_range.clone(),
            if show_title { "1" } else { "0" }.to_string(),
        ));
    }
    if item.tag == "InputField"
        && let Some(title_location) = item.title_location
        && let Some(title_location_range) = fields.get(7)
    {
        replacements.push((
            title_location_range.clone(),
            form_input_field_title_location_code(title_location).to_string(),
        ));
    }
    if item.tag == "TextDocumentField"
        && let Some(title_location) = item.title_location
        && let Some(title_location_range) = fields.get(7)
    {
        replacements.push((
            title_location_range.clone(),
            form_input_field_title_location_code(title_location).to_string(),
        ));
    }
    if item.tag == "InputField"
        && form_layout_input_field_is_extended(fields)
        && let Some(edit_mode) = form_input_field_edit_mode_code(item)
        && let Some(edit_mode_range) = fields.get(26)
    {
        replacements.push((edit_mode_range.clone(), edit_mode.to_string()));
    }
    if item.tag == "InputField"
        && form_layout_input_field_is_extended(fields)
        && let Some(auto_cell_height) = item.auto_cell_height
    {
        let index = 28 + form_layout_input_field_top_level_offset(text, fields);
        if let Some(auto_cell_height_range) = fields.get(index) {
            replacements.push((
                auto_cell_height_range.clone(),
                if auto_cell_height { "1" } else { "0" }.to_string(),
            ));
        }
    }
    if matches!(
        item.tag.as_str(),
        "InputField" | "LabelField" | "CheckBoxField"
    ) && form_layout_input_field_is_extended(fields)
        && let Some(show_in_header) = item.show_in_header
    {
        let index = 20 + form_layout_input_field_top_level_offset(text, fields);
        if let Some(show_in_header_range) = fields.get(index) {
            replacements.push((
                show_in_header_range.clone(),
                if show_in_header { "1" } else { "0" }.to_string(),
            ));
        }
    }
    if item.tag == "InputField"
        && let Some(choice_folders_and_items) = item.choice_folders_and_items
    {
        let choice_range = form_layout_input_field_choice_folders_and_items_range(text, fields)
            .ok_or_else(|| {
                anyhow!(
                    "cannot patch Form InputField {} ChoiceFoldersAndItems without an existing strict FormField layout",
                    item.name
                )
            })?;
        replacements.push((
            choice_range,
            form_use_for_folders_and_items_code(choice_folders_and_items).to_string(),
        ));
    }
    if item.tag == "InputField"
        && form_layout_input_field_is_extended(fields)
        && let Some(options_range) = form_layout_input_field_extended_options_range(text, fields)?
        && let Some(options) =
            patch_form_layout_input_field_extended_options(&text[options_range.clone()], item)
                .with_context(|| {
                    format!(
                        "failed to patch Form layout input options for {}",
                        item.name
                    )
                })?
    {
        replacements.push((options_range.clone(), options));
    }
    if item.tag == "Pages"
        && let Some(height) = &item.height
        && let Some(height_range) = fields.get(13)
    {
        replacements.push((height_range.clone(), height.to_string()));
    }
    if item.tag == "TextDocumentField"
        && let Some(width) = &item.width
        && let Some(width_range) = fields.get(22)
    {
        replacements.push((width_range.clone(), width.to_string()));
    }
    if item.tag == "TextDocumentField"
        && let Some(height) = &item.height
        && let Some(height_range) = fields.get(23)
    {
        replacements.push((height_range.clone(), height.to_string()));
    }
    if item.tag == "Page"
        && let Some(scroll_on_compress) = item.scroll_on_compress
        && let Some(scroll_range) = form_layout_page_scroll_on_compress_range(text, fields, item)
    {
        replacements.push((
            scroll_range.clone(),
            if scroll_on_compress { "1" } else { "0" }.to_string(),
        ));
    }
    if item.tag.ends_with("Addition")
        && let Some(item_type) = &item.item_type
        && let Some(type_code) = form_search_addition_type_code(item_type)
        && let Some(type_range) = fields.get(5)
    {
        replacements.push((type_range.clone(), type_code.to_string()));
    }
    if item.tag.ends_with("Addition")
        && let Some(source_item) = &item.addition_source_item
        && let Some(source_item_id) = table_ids_by_name.get(source_item)
        && let Some(item_type) = &item.item_type
        && let Some(type_code) = form_search_addition_type_code(item_type)
        && let Some(source_range) = fields.get(19)
    {
        replacements.push((
            source_range.clone(),
            format!("{{{source_item_id},{type_code}}}"),
        ));
    }
    if item.tag == "Button"
        && let Some(command_name) = &item.command_name
        && let Some(command_range) = fields.get(8)
        && let Some(command_ref) = format_form_button_command_reference(
            &text[command_range.clone()],
            command_name,
            commands,
            source,
        )?
    {
        replacements.push((command_range.clone(), command_ref));
    }
    if item.tag == "Button"
        && let Some(data_path) = &item.data_path
        && let Some(data_path_range) = fields.get(9)
        && let Some(data_path_ref) =
            format_form_button_data_path(data_path, table_ids_by_name, table_column_ids_by_name)
    {
        replacements.push((data_path_range.clone(), data_path_ref));
    }
    if item.tag == "TextDocumentField"
        && let Some(data_path) = &item.data_path
        && let Some(data_path_range) = fields.get(11)
        && let Some(data_path_ref) = form_attribute_data_path_replacement(
            &text[data_path_range.clone()],
            data_path,
            attribute_ids_by_name,
        )
    {
        replacements.push((data_path_range.clone(), data_path_ref));
    }
    if item.tag == "InputField"
        && let Some(data_path) = &item.data_path
        && let Some(data_path_range) = fields.get(11)
        && text[data_path_range.clone()].trim_start().starts_with('{')
        && let Some(data_path_ref) = form_attribute_data_path_replacement(
            &text[data_path_range.clone()],
            data_path,
            attribute_ids_by_name,
        )
    {
        replacements.push((data_path_range.clone(), data_path_ref));
    }
    if matches!(
        item.tag.as_str(),
        "CommandBar"
            | "AutoCommandBar"
            | "UsualGroup"
            | "Popup"
            | "Pages"
            | "Page"
            | "ButtonGroup"
            | "ContextMenu"
    ) && let Some(group) = item.group
        && form_layout_usual_group_extended_options_range(text, fields).is_none()
        && let Some(group_code) = form_child_group_code(group)
        && let Some(group_range) = form_layout_child_item_group_range(text, fields, item)
    {
        replacements.push((group_range.clone(), group_code.to_string()));
    }
    if item.tag == "UsualGroup"
        && (item.group.is_some() || item.behavior.is_some() || item.representation.is_some())
        && let Some(options_range) = form_layout_usual_group_extended_options_range(text, fields)
        && let Some(options) =
            patch_form_layout_usual_group_extended_options(&text[options_range.clone()], item)
                .with_context(|| {
                    format!(
                        "failed to patch Form layout group options for {}",
                        item.name
                    )
                })?
    {
        replacements.push((options_range, options));
    }
    if item.tag == "AutoCommandBar"
        && (item.horizontal_align.is_some() || item.autofill.is_some())
        && let Some(settings_range) = fields.get(20)
        && let Some(settings) = format_form_auto_command_bar_settings(
            &text[settings_range.clone()],
            item.horizontal_align,
            item.autofill,
        )?
    {
        replacements.push((settings_range.clone(), settings));
    }
    if item.tag == "UsualGroup" {
        if item.title_text_color.is_some() {
            let style_range = fields.get(16).ok_or_else(|| {
                anyhow!(
                    "Form UsualGroup TitleTextColor slot is missing for {}",
                    item.name
                )
            })?;
            let replacement = form_existing_extended_group_title_text_color(
                item,
                source,
                &text[style_range.clone()],
            )?;
            if !one_c_values_equal_ignoring_ws(&text[style_range.clone()], &replacement) {
                replacements.push((style_range.clone(), replacement));
            }
        }
        if item.title_font.is_some() {
            let font_range = fields.get(17).ok_or_else(|| {
                anyhow!(
                    "Form UsualGroup TitleFont slot is missing for {}",
                    item.name
                )
            })?;
            let replacement =
                form_existing_extended_group_title_font(item, source, &text[font_range.clone()])?;
            if !one_c_values_equal_ignoring_ws(&text[font_range.clone()], &replacement) {
                replacements.push((font_range.clone(), replacement));
            }
        }
    }
    if matches!(
        item.tag.as_str(),
        "CommandBar"
            | "AutoCommandBar"
            | "UsualGroup"
            | "Popup"
            | "Pages"
            | "Page"
            | "ButtonGroup"
            | "ContextMenu"
    ) && let Some(show_title) = item.show_title
        && let Some(show_title_range) = form_layout_child_item_show_title_range(text, fields, item)
    {
        replacements.push((
            show_title_range.clone(),
            if show_title { "1" } else { "0" }.to_string(),
        ));
    }
    if item.tag == "ColumnGroup"
        && (item.group.is_some() || item.show_in_header.is_some() || item.fixing_in_table.is_some())
    {
        let options_range = form_layout_column_group_options_range(text, fields);
        if options_range.is_none() && item.fixing_in_table.is_some() {
            return Err(anyhow!(
                "Form ColumnGroup FixingInTable requires a supported strict layout for {}",
                item.name
            ));
        }
        if let Some(options_range) = options_range
            && let Some(options) = patch_form_layout_column_group_options(
                &text[options_range.clone()],
                item,
                wrapper,
                fields.len(),
                fields.get(5).map(|range| text[range.clone()].trim()),
            )
            .with_context(|| {
                format!(
                    "failed to patch Form layout column group options for {}",
                    item.name
                )
            })?
        {
            replacements.push((options_range, options));
        }
    }

    replacements.sort_by_key(|(range, _)| range.start);
    for (range, replacement) in replacements.into_iter().rev() {
        text.replace_range(range, &replacement);
    }
    patch_form_layout_events(text, &item.events, false)
        .with_context(|| format!("failed to patch Form layout events for {}", item.name))?;
    patch_form_layout_direct_child_items(
        text,
        item,
        commands,
        attribute_ids_by_name,
        table_ids_by_name,
        table_column_ids_by_name,
        command_uuids,
        source,
    )
    .with_context(|| {
        format!(
            "failed to patch Form layout direct child items for {}",
            item.name
        )
    })?;
    patch_form_layout_single_child_items(
        text,
        item,
        commands,
        attribute_ids_by_name,
        table_ids_by_name,
        table_column_ids_by_name,
        command_uuids,
        source,
    )
    .with_context(|| {
        format!(
            "failed to patch Form layout single child items for {}",
            item.name
        )
    })?;
    Ok(())
}

fn form_layout_child_item_group_range(
    text: &str,
    fields: &[Range<usize>],
    item: &FormXmlChildItem,
) -> Option<Range<usize>> {
    if matches!(item.tag.as_str(), "Pages" | "Page") {
        for index in [8, 9] {
            let range = fields.get(index)?.clone();
            if form_child_group_code(item.group?) == Some(text[range.clone()].trim()) {
                return Some(range);
            }
            if !text[range.clone()].trim_start().starts_with('{') {
                return Some(range);
            }
        }
        None
    } else {
        fields.get(8).cloned()
    }
}

fn form_layout_child_item_show_title_range(
    text: &str,
    fields: &[Range<usize>],
    item: &FormXmlChildItem,
) -> Option<Range<usize>> {
    if matches!(item.tag.as_str(), "Pages" | "Page")
        && fields
            .get(8)
            .is_some_and(|range| text[range.clone()].trim_start().starts_with('{'))
    {
        return fields.get(10).cloned();
    }
    fields.get(9).cloned()
}

fn form_layout_page_scroll_on_compress_range(
    text: &str,
    fields: &[Range<usize>],
    item: &FormXmlChildItem,
) -> Option<Range<usize>> {
    if item.tag != "Page" {
        return None;
    }
    fields
        .get(8)
        .filter(|range| text[(*range).clone()].trim_start().starts_with('{'))?;
    fields.get(11).cloned()
}

fn form_layout_button_is_extended(fields: &[Range<usize>]) -> bool {
    fields.len() > 20
}

fn form_layout_input_field_is_extended(fields: &[Range<usize>]) -> bool {
    fields.len() > 20
}

fn form_layout_input_field_top_level_offset(text: &str, fields: &[Range<usize>]) -> usize {
    fields
        .get(6)
        .and_then(|range| parse_1c_quoted_string(&text[range.clone()]).ok())
        .filter(|value| !value.is_empty())
        .map(|_| 0)
        .unwrap_or(1)
}

fn form_layout_input_field_extended_options_range(
    text: &str,
    fields: &[Range<usize>],
) -> Result<Option<Range<usize>>> {
    for range in fields.iter().skip(39) {
        let value = text[range.clone()].trim();
        if !value.starts_with('{') {
            continue;
        }
        let nested = scan_braced_fields(value, 0)?;
        if nested.first().map(|field| value[field.clone()].trim()) == Some("38") {
            return Ok(Some(range.clone()));
        }
    }
    Ok(None)
}

fn form_layout_usual_group_extended_options_range(
    text: &str,
    fields: &[Range<usize>],
) -> Option<Range<usize>> {
    let wrapper = fields.first().map(|range| text[range.clone()].trim())?;
    if wrapper != "22" || fields.get(5).map(|range| text[range.clone()].trim()) != Some("5") {
        return None;
    }
    let range = fields.get(20)?.clone();
    text[range.clone()]
        .trim_start()
        .starts_with("{38")
        .then_some(range)
}

fn form_layout_column_group_options_range(
    text: &str,
    fields: &[Range<usize>],
) -> Option<Range<usize>> {
    let wrapper = fields.first().map(|range| text[range.clone()].trim())?;
    if wrapper != "22" || fields.get(5).map(|range| text[range.clone()].trim()) != Some("2") {
        return None;
    }
    let range = fields.get(FormColumnGroupSchema::OPTIONS_SLOT)?.clone();
    if scan_1c_braced_value_range(text, range.start) != Some(range.clone()) {
        return None;
    }
    let options = scan_braced_fields(text, range.start).ok()?;
    matches!(
        options.first().map(|field| text[field.clone()].trim()),
        Some("2" | "5")
    )
    .then_some(range)
}

fn patch_form_layout_column_group_options(
    existing: &str,
    item: &FormXmlChildItem,
    wrapper: &str,
    field_count: usize,
    direct_discriminator: Option<&str>,
) -> Result<Option<String>> {
    let mut text = existing.trim().to_string();
    let fields = scan_braced_fields(&text, 0)?;
    let option_values = fields
        .iter()
        .map(|range| &text[range.clone()])
        .collect::<Vec<_>>();
    let options_kind = option_values.first().map(|value| value.trim());
    if !matches!(options_kind, Some("2" | "5")) {
        return Ok(None);
    }
    let strict_schema = FormColumnGroupSchema::from_raw_layout(
        wrapper,
        field_count,
        item.tag.as_str(),
        direct_discriminator,
        &option_values,
    );
    let mut replacements = Vec::<(usize, &'static str)>::new();
    if options_kind == Some("5")
        && let Some(group) = item.group
        && let Some(code) = form_column_group_group_code(group)
    {
        replacements.push((1, code));
    }
    if options_kind == Some("5")
        && let Some(show_in_header) = item.show_in_header
    {
        replacements.push((3, if show_in_header { "1" } else { "0" }));
    }
    if let Some(fixing_in_table) = item.fixing_in_table {
        let schema = strict_schema.ok_or_else(|| {
            anyhow!(
                "Form ColumnGroup FixingInTable requires a supported strict options tuple for {}",
                item.name
            )
        })?;
        let raw_code = schema
            .fixing_in_table_raw_code(fixing_in_table)
            .ok_or_else(|| {
                anyhow!(
                    "unsupported Form ColumnGroup FixingInTable value for {}",
                    item.name
                )
            })?;
        replacements.push((FormColumnGroupSchema::FIXING_IN_TABLE_OPTION_SLOT, raw_code));
    }
    if replacements.is_empty() {
        return Ok(None);
    }
    replacements.sort_by_key(|(index, _)| *index);
    replacements.dedup_by_key(|(index, _)| *index);
    for (index, value) in replacements.into_iter().rev() {
        replace_braced_field(&mut text, index, value)?;
    }
    Ok(Some(text))
}

fn patch_form_layout_usual_group_extended_options(
    existing: &str,
    item: &FormXmlChildItem,
) -> Result<Option<String>> {
    let mut text = existing.trim().to_string();
    let fields = scan_braced_fields(&text, 0)?;
    if fields.first().map(|range| text[range.clone()].trim()) != Some("38") {
        return Ok(None);
    }
    let mut replacements = Vec::<(usize, &'static str)>::new();
    if let Some(representation) = item.representation
        && let Some(code) = form_extended_group_representation_code(representation)
    {
        replacements.push((3, code));
        replacements.push((35, code));
    }
    if let Some(group) = item.group
        && let Some((orientation_code, group_code, layout_code, mirror_code)) =
            form_extended_group_group_codes(group)
    {
        replacements.push((1, orientation_code));
        replacements.push((22, group_code));
        replacements.push((27, layout_code));
        replacements.push((36, mirror_code));
    }
    if let Some(behavior) = item.behavior {
        let (marker_code, flag10, flag11, flag24, flag28) =
            form_extended_group_behavior_codes(behavior);
        let marker_code = if behavior == FormXmlGroupBehavior::Usual
            && item.group == Some(FormXmlGroup::AlwaysHorizontal)
        {
            "1"
        } else {
            marker_code
        };
        replacements.push((4, marker_code));
        replacements.push((10, flag10));
        replacements.push((11, flag11));
        replacements.push((24, flag24));
        replacements.push((28, flag28));
    }
    if replacements.is_empty() {
        return Ok(None);
    }
    replacements.sort_by_key(|(index, _)| *index);
    replacements.dedup_by_key(|(index, _)| *index);
    for (index, value) in replacements.into_iter().rev() {
        replace_braced_field(&mut text, index, value)?;
    }
    Ok(Some(text))
}

