    #[test]
    fn parses_chart_drawing_into_typed_ir() -> anyhow::Result<()> {
        let xml = br#"<?xml version="1.0" encoding="UTF-8"?>
<document xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance">
  <rowsItem><index>0</index></rowsItem>
  <drawing>
    <drawingType>Chart</drawingType>
    <id>7</id>
    <formatIndex>3</formatIndex>
    <object xmlns:d3p1="http://v8.1c.ru/8.2/data/chart" xsi:type="d3p1:Chart"/>
  </drawing>
</document>"#;
        let parsed = super::parse_spreadsheet_document_xml(xml)?;
        assert_eq!(parsed.drawings.len(), 1);
        assert_eq!(parsed.drawings[0].id, 7);
        assert!(matches!(
            parsed.drawings[0].kind,
            super::SpreadsheetDocumentXmlDrawingKind::Chart(Some(_))
        ));
        Ok(())
    }

    #[test]
    fn rejects_chart_xml_beyond_depth_limit() {
        let depth = super::MAX_SPREADSHEET_CHART_XML_DEPTH + 1;
        let mut xml = String::from(
            r#"<document xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance"><drawing><object xsi:type="d3p1:Chart">"#,
        );
        xml.push_str(&"<x>".repeat(depth));
        xml.push_str(&"</x>".repeat(depth));
        xml.push_str("</object></drawing></document>");

        assert!(super::parse_spreadsheet_chart_objects(xml.as_bytes()).is_err());
    }

    #[test]
    fn rejects_multi_series_spreadsheet_chart_without_partial_moxel() {
        let series = || super::SpreadsheetChartXmlNode {
            name: "realSeriesData".to_string(),
            attributes: std::collections::BTreeMap::new(),
            text: String::new(),
            children: Vec::new(),
        };
        let chart = super::SpreadsheetDocumentXmlChart {
            object: super::SpreadsheetChartXmlNode {
                name: "object".to_string(),
                attributes: std::collections::BTreeMap::from([(
                    "type".to_string(),
                    "d3p1:Chart".to_string(),
                )]),
                text: String::new(),
                children: vec![series(), series()],
            },
        };
        let drawing = super::SpreadsheetDocumentXmlDrawing {
            kind: super::SpreadsheetDocumentXmlDrawingKind::Chart(Some(chart)),
            ..Default::default()
        };
        let super::SpreadsheetDocumentXmlDrawingKind::Chart(Some(chart)) = &drawing.kind else {
            unreachable!();
        };

        assert!(
            super::format_spreadsheet_chart_drawing_for_moxel(
                &drawing,
                drawing.format_index,
                chart,
            )
            .is_none(),
            "unsupported multi-series charts must not produce partial MOXCEL"
        );
    }

    fn decode_base64_for_test(input: &str) -> anyhow::Result<Vec<u8>> {
        fn value(byte: u8) -> anyhow::Result<u8> {
            match byte {
                b'A'..=b'Z' => Ok(byte - b'A'),
                b'a'..=b'z' => Ok(byte - b'a' + 26),
                b'0'..=b'9' => Ok(byte - b'0' + 52),
                b'+' => Ok(62),
                b'/' => Ok(63),
                _ => anyhow::bail!("invalid base64 byte {byte}"),
            }
        }

        let bytes: Vec<u8> = input
            .bytes()
            .filter(|byte| !byte.is_ascii_whitespace())
            .collect();
        let mut output = Vec::with_capacity(bytes.len() / 4 * 3);
        for chunk in bytes.chunks(4) {
            if chunk.len() != 4 {
                anyhow::bail!("invalid base64 length");
            }
            let first = value(chunk[0])?;
            let second = value(chunk[1])?;
            let third = if chunk[2] == b'=' {
                0
            } else {
                value(chunk[2])?
            };
            let fourth = if chunk[3] == b'=' {
                0
            } else {
                value(chunk[3])?
            };
            output.push((first << 2) | (second >> 4));
            if chunk[2] != b'=' {
                output.push((second << 4) | (third >> 2));
            }
            if chunk[3] != b'=' {
                output.push((third << 6) | fourth);
            }
        }
        Ok(output)
    }

    fn form_setting_base64_xml_for_test(text: &str, key: &str) -> anyhow::Result<String> {
        let key_start = text
            .find(&format!("\"{key}\""))
            .ok_or_else(|| anyhow::anyhow!("setting {key} not found"))?;
        let payload_prefix = "{#base64:";
        let payload_start = text[key_start..]
            .find(payload_prefix)
            .map(|relative| key_start + relative + payload_prefix.len())
            .ok_or_else(|| anyhow::anyhow!("setting {key} base64 payload not found"))?;
        let payload_end = text[payload_start..]
            .find('}')
            .map(|relative| payload_start + relative)
            .ok_or_else(|| anyhow::anyhow!("setting {key} base64 payload is not closed"))?;
        let bytes = decode_base64_for_test(&text[payload_start..payload_end])?;
        let bytes = bytes.strip_prefix(b"\xEF\xBB\xBF").unwrap_or(&bytes);
        String::from_utf8(bytes.to_vec()).map_err(Into::into)
    }

    #[test]
    fn packs_module_inner_with_plain_info_and_text() {
        let inner = build_module_inner(&[
            V8Element {
                name: "info".to_string(),
                header: make_v8_element_header("info"),
                data: DEFAULT_INFO.to_vec(),
            },
            V8Element {
                name: "text".to_string(),
                header: make_v8_element_header("text"),
                data: b"\xEF\xBB\xBFProcedure Test()\r\nEndProcedure".to_vec(),
            },
        ])
        .unwrap();

        assert_eq!(&inner[0..4], &0x7fff_ffff_u32.to_le_bytes());
        assert_eq!(&inner[8..12], &1_u32.to_le_bytes());

        let elements = parse_v8_container(&inner).unwrap();
        assert_eq!(elements.len(), 2);
        assert_eq!(elements[0].name, "info");
        assert_eq!(elements[0].data, DEFAULT_INFO);
        assert_eq!(elements[1].name, "text");
        assert!(elements[1].data.ends_with(b"EndProcedure"));
    }

